window.TXB=window.TXB||{};TXB["alab/Lev"]={"1:1":"واستدعى الرب موسى، وخاطبه من خيمة الاجتماع قائلا:","1:2":"«أوص بني إسرائيل: إذا قدم أحدكم ذبيحة من البهائم للرب، فليكن ذلك القربان من البقر والغنم.","1:3":"إن كانت تقدمته محرقة من البقر، فليقرب ثورا سليما، يحضره عند مدخل خيمة الاجتماع، ويقدمه أمام الرب طلبا لرضاه عنه.","1:4":"فيضع يده على رأس المحرقة، فيرضى الرب بموت الثور بديلا عن صاحبه، للتكفير عن خطاياه.","1:5":"ثم يذبح المقرب العجل أمام الرب. ويقدم بنو هرون، الكهنة، الدم ويرشونه على جوانب المذبح القائم عند مدخل خيمة الاجتماع.","1:6":"وعلى المقرب أيضا أن يسلخ المحرقة ويقطعها إلى أجزاء.","1:7":"ويوقد أبناء هرون نارا على المذبح ويرتبون عليها حطبا","1:8":"ثم يرتبون فوق حطب نار المذبح أجزاء الثور ورأسه وشحمه.","1:9":"أما أعضاؤه الداخلية وأكارعه فيغسلها المقرب بماء، ثم يحرقها الكاهن جميعا على المذبح، فتكون محرقة، وقود رضى تسر الرب.","1:10":"وإن كانت محرقته من الماشية: الضأن أو المعز، فلتكن ذكرا سليما.","1:11":"وعلى المقرب أن يذبحه في حضرة الرب، عند الجانب الشمالي للمذبح، ثم يقوم أبناء هرون الكهنة برش دمه على جوانب المذبح.","1:12":"ويقطعه المقرب إلى أجزاء مع رأسه وشحمه، فيرتبها الكاهن فوق حطب نار المذبح،","1:13":"وأما الأعضاء الداخلية والأكارع فيغسلها بماء، ثم يحرقها الكاهن جميعها فتكون محرقة ووقود رضى تسر الرب.","1:14":"وإن كانت تقدمته للرب محرقة من الطير، فلتكن من اليمام أو من أفراخ الحمام.","1:15":"فيقدم الكاهن القربان إلى المذبح ويحز رأسه ويصفي دمه على حائط المذبح بعد إيقاد النار على المذبح،","1:16":"وينزع حوصلته بكل ما بها ويطرحهما إلى جانب المذبح الشرقي، حيث يجمع الرماد.","1:17":"ويشق الكاهن الطائر من بين جناحيه، من غير أن يفصله إلى قطعتين، ويحرقه على المذبح فوق حطب النار، فيكون محرقة ووقود رضى تسر الرب.","2:1":"وإذا قدم أحد للرب تقدمة من حنطة، فلتكن من دقيق يسكب عليها زيتا ويضع عليها لبانا،","2:2":"ثم يحضرها إلى أبناء هرون الكهنة، فيملأ الكاهن قبضته من دقيق التقدمة وزيتها مع كل لبانها ويوقدها الكاهن تذكارا على المذبح، فتكون وقود محرقة رضى تسر الرب.","2:3":"أما بقية التقدمة فتكون من نصيب هرون وأبنائه، فهي تقدمة محرقة مقدسة للرب.","2:4":"إن كان القربان تقدمة مخبوزة في تنور، فلتكن أقراصا من دقيق فطيرا ملتوتة أو مدهونة بزيت.","2:5":"وإن كان قربانك مخبوزا على الصاج، فلتكن من دقيق فطيرا ملتوتة بزيت.","2:6":"قطعها إلى فتات وصب عليها زيتا؛ إنها تقدمة.","2:7":"وإن كانت تقدمتك مخبوزة في مقلاة، فلتكن من دقيق معجون بزيت.","2:8":"فتحضر التقدمة، سواء أكانت مخبوزة في فرن أم على الصاج أم في مقلاة، إلى الكاهن وهو يقترب بها إلى المذبح.","2:9":"ويتناول من التقدمة جزءا تذكاريا ويحرقه على المذبح، فيكون وقود محرقة رضى تسر الرب.","2:10":"أما بقية التقدمة فتكون من نصيب هرون وأبنائه، فهي تقدمة محرقة مقدسة للرب.","2:11":"لا تضعوا خميرا في كل تقدمة دقيق تقدمونها للرب. كل قربان فيه خمير أو عسل لا تقدموه محرقة للرب.","2:12":"يمكن أن تقدموا للرب خبزا مختمرا وعسلا كقرابين بواكير الحصاد، ولكنها لا تصعد على المذبح كمحرقات رضى وسرور.","2:13":"عليك أن تملح تقدماتك. إياك أن تخلي تقدمتك من ملح عهد إلهك. مع جميع تقدماتك قرب ملحا.","2:14":"وإن قدمت قربانا من بواكير حصادك، فليكن فريكا مشويا بنار، تنزع حبه من رؤوس سنابله الطرية وتجرشه وتشويه، ثم تقدمه باكورة حصادك،","2:15":"بعد أن تصب عليه زيتا وتضع فوقه لبانا. إنه تقدمة.","2:16":"ثم يحرق الكاهن منه جزءا تذكاريا مع زيته وجميع لبانه، فيكون محرقة للرب.","3:1":"وإن قرب أحد ذبيحة سلام من بقر، ثورا أو عجلة، فليقدم قربانا للرب سليما من كل عيب،","3:2":"فيضع المقرب يده على رأس تقدمته ويذبحها عند باب خيمة الاجتماع، ثم يرش أبناء هرون، الكهنة، الدم على جوانب المذبح، المحيطة به.","3:3":"ويحرق الكاهن أمام الرب من ذبيحة السلام، جميع شحم الأعضاء الداخلية","3:4":"والكليتين وشحمهما الذي على الخاصرتين والمرارة.","3:5":"فيوقدها أبناء هرون على المذبح، على المحرقة التي فوق حطب النار، فتكون محرقة ووقود رضى تسر الرب.","3:6":"وإن قرب ذبيحة سلام من غنم، ذكرا أو أنثى، فليقدم قربانا للرب سليما من كل عيب.","3:7":"وإن كان القربان من الضأن، فليقدمه أمام الرب.","3:8":"ويضع يده على رأس تقدمته ويذبحها عند خيمة الاجتماع، فيرش أبناء هرون دمها على جوانب المذبح المحيطة به.","3:9":"ويحرق الكاهن أمام الرب من ذبيحة السلام شحمها، فينزع كامل الألية من عند العصعص وجميع شحم الأعضاء الداخلية","3:10":"والكليتين وشحمهما الذي على الخاصرتين، والمرارة،","3:11":"ويحرقها الكاهن على المذبح طعام وقود للرب.","3:12":"وإن كان قربانه من المعز فليقدمه أمام الرب،","3:13":"فيضع يده على رأس تقدمته ويذبحها عند خيمة الاجتماع، فيرش أبناء هرون دمها على جوانب المذبح المحيطة به.","3:14":"ويحرق الكاهن أمام الرب من ذبيحته جميع شحم الأعضاء الداخلية،","3:15":"وينزع كذلك الكليتين وشحمهما الذي على الخاصرتين والمرارة.","3:16":"ويحرقها الكاهن على المذبح طعام وقود رضى وسرور، فيكون كل الشحم للرب.","3:17":"لا تأكلوا الشحم ولا الدم. هذا فرض دائم عليكم حيث تقيمون، جيلا بعد جيل».","4:1":"وقال الرب لموسى:","4:2":"«أوص بني إسرائيل: إن سهت نفس فأخطأت في أمر من كل نواهي الرب، واقترفت ما لا ينبغي، فهذا ما تفعلونه:","4:3":"إن أخطأ الكاهن الممسوح سهوا، وجلب على الشعب إثما، فليقدم للرب عن خطيئته التي ارتكبها ثورا لا عيب فيه، ذبيحة خطيئة.","4:4":"فيحضر الثور إلى مدخل خيمة الاجتماع في حضرة الرب، ويضع يده على رأسه ويذبحه أمام الرب.","4:5":"ويأخذ الكاهن الممسوح من دم الثور ويدخل به إلى خيمة الاجتماع،","4:6":"ثم يغمس إصبعه في الدم ويرش منه سبع مرات أمام الرب عند حجاب القدس، الفاصل بين القدس وقدس الأقداس.","4:7":"ثم يضع الكاهن بعض الدم على قرون مذبح البخور العطر الذي في داخل القدس في حضرة الرب. أما بقية دم الثور فيصبه عند قاعدة مذبح المحرقة، القائم عند مدخل خيمة الاجتماع.","4:8":"وينزع جميع شحم ثور الخطيئة وشحم الأعضاء الداخلية كلها،","4:9":"والكليتين وشحمهما الذي على الخاصرتين والمرارة،","4:10":"على غرار ما يفعل بثور ذبيحة السلام، ويحرقها الكاهن على مذبح المحرقة.","4:11":"أما جلد الثور وكل لحمه مع رأسه وأكارعه وأمعائه وفرثه","4:12":"فإنه يحملها إلى خارج المخيم إلى مكان طاهر، حيث يطرح الرماد، فيحرقها كلها على حطب مشتعل فوق مكان إلقاء الرماد.","4:13":"وإن أخطأ شعب إسرائيل كله سهوا، واقترفوا إحدى نواهي الرب التي لا ينبغي اقترافها، وأثموا، وكان المجمع غافلا عن الأمر،","4:14":"ثم اكتشف المجمع الخطيئة المرتكبة، عندئذ يقرب المجمع ثورا ذبيحة خطيئة، يحضرونه أمام الرب عند خيمة الاجتماع.","4:15":"ويضع شيوخ الشعب أيديهم على رأس الثور في حضرة الرب، ويذبحونه هناك،","4:16":"ويأخذ الكاهن الممسوح من دم الثور ويدخل به إلى خيمة الاجتماع،","4:17":"ثم يغمس إصبعه في الدم ويرش منه سبع مرات أمام الرب عند حجاب «القدس»","4:18":"وكذلك يضع بعض الدم على قرون مذبح البخور العطر الذي في داخل «القدس» في حضرة الرب. أما بقية الدم فيصبه عند قاعدة مذبح المحرقة القائم عند مدخل خيمة الاجتماع.","4:19":"وينزع الكاهن جميع شحمه ويحرقه على المذبح.","4:20":"ويفعل بالثور كما فعل بثور الخطيئة، فيكفر عنهم الكاهن ويغفر الله لهم.","4:21":"ثم يحمل بقية الثور إلى خارج المخيم ويحرقه كما أحرق الثور الأول، فيكون ذبيحة خطيئة عن كل الشعب.","4:22":"إن أخطأ أحد قادة الشعب سهوا، واقترف إحدى نواهي الرب التي لا ينبغي اقترافها وأثم،","4:23":"ثم تنبه إلى خطئه الذي ارتكبه، فإنه يحضر قربانا، جديا ذكرا سليما من كل عيب،","4:24":"ويضع يده على رأس الجدي ويذبحه في الجانب الشمالي لمذبح المحرقة، أمام الرب. فيكون ذبيحة خطيئة.","4:25":"ويأخذ الكاهن من دم ذبيحة الخطيئة بإصبعه ويضعه على قرون مذبح المحرقة.","4:26":"ويحرق جميع شحمه على المذبح، كما فعل بشحم ذبيحة السلام. وهكذا يكفر الكاهن عن خطيئته، فيغفر الرب له.","4:27":"وإن أخطأ واحد من عامة الشعب سهوا واقترف إحدى نواهي الرب التي لا ينبغي اقترافها وأثم،","4:28":"ثم نبه إلى خطيئته التي ارتكبها، فإنه يحضر قربانا: عنزا أنثى سليمة من كل عيب للتكفير عن خطيئته التي ارتكبها.","4:29":"ويضع يده على رأس ذبيحة الخطيئة ويذبحها عند موضع المحرقة،","4:30":"فيأخذ الكاهن من دمها ويضعه على قرون مذبح المحرقة، ويصب بقية دمها عند قاعدة المذبح.","4:31":"ثم ينتزع الكاهن جميع شحمها على غرار ما فعل بشحم ذبيحة السلام، ويحرقها على المذبح تقدمة رضى وسرور للرب فيكفر الكاهن عنه ويغفر الرب له.","4:32":"وإن أحضر قربانه من الضأن لتكون ذبيحة خطيئة، فليكن نعجة سليمة من كل عيب،","4:33":"فيضع يده على رأسها ويذبحها قربان خطيئة، في الموضع الذي تذبح فيه المحرقة.","4:34":"ويأخذ الكاهن من دم ذبيحة الخطيئة بإصبعه ويضعه على قرون مذبح المحرقة، ويصب بقية الدم عند قاعدة المذبح.","4:35":"وينزع جميع شحمها على غرار ما فعل بشحم ذبيحة السلام، ويحرقه على المذبح فوق وقائد الرب. وهكذا يكفر الكاهن عن خطيئته التي ارتكبها، ويغفر الرب له.","5:1":"إذا أخطأ أحد لأنه صمت عندما استحلف، ولم يدل بشهادته حول جريمة رآها أو علم بها، فإنه يكون شريكا في الذنب.","5:2":"كل من يلمس شيئا نجسا، سواء أكان جثة حيوان محرم أكله، أم جثة وحش أو حشرة محرمة، يكون مذنبا ونجسا، حتى لو لم يعلم أنه لمسها.","5:3":"كل من يمس إحدى نجاسات الإنسان التي يتنجس بها، عن غير علم منه، ثم نبه إلى الأمر، يصبح مذنبا.","5:4":"كل من يحلف بشفتيه دون أن يتفكر، سواء للإحسان أو للإساءة من جميع الأحلاف التي يفرط بها اللسان، من غير علم منه، ثم نبه إلى الأمر، يصبح مذنبا في كلا الحالين.","5:5":"فكل من يكون مذنبا في أحد هذه الأمور، عليه الإقرار بما أخطأ به،","5:6":"ثم يحضر إلى الرب ذبيحة إثم عن خطيئته التي اقترفها: نعجة أو عنزة، فيكفر الكاهن عن خطيئته.","5:7":"وإن كان فقيرا، غير قادر على إحضار شاة، فليقدم إلى الرب ذبيحة عن إثمه الذي ارتكبه يمامتين أو فرخي حمام، فيكون أحدها ذبيحة خطيئة والآخر محرقة،","5:8":"فيأخذ الكاهن ذبيحة الخطيئة أولا، ويقربها بأن يحز رأسها من الخلف ولا يفصله،","5:9":"ويرش بعض دمها على حائط المذبح، ويصفي بقية الدم عند قاعدة المذبح. إنها ذبيحة خطيئة.","5:10":"ثم يقدم الثاني محرقة وفقا للنظام المتبع، وهكذا يكفر الكاهن عن خطيئة المذنب ويغفر الرب له.","5:11":"وإن كان المذنب أفقر من أن يقدم يمامتين أو فرخي حمام، فليحضر قربانا عن خطيئته. عشر الإيفة (نحو لترين ونصف اللتر) من دقيق ناعم، لا يضع عليه زيتا أو لبانا، لأنه قربان خطيئة،","5:12":"ويقدمه إلى الكاهن، فيملأ منه قبضته للتذكار، ويحرقه على المذبح، على وقائد الرب. إنه قربان خطيئة.","5:13":"فيكفر الكاهن بذلك عن أي خطيئة من الخطايا السالفة التي ارتكبها، فيغفر الرب له. أما بقية التقدمة فتكون من نصيب الكاهن على غرار تقدمة الدقيق».","5:14":"قال الرب لموسى:","5:15":"«إن سها أحد وتعدى على واحد من أقداس الرب، يحضر إلى الرب ذبيحة إثم: كبشا سليما، يقدر الكاهن قيمته من الفضة وفقا للمعايير المستعملة في القدس،","5:16":"فيعوض عما أخطأ به من القدس، بعد أن يضيف عليه ما يعادل خمسه غرامة، ويؤديه للكاهن. فيكفر الكاهن عنه بكبش الإثم، ويغفر الرب له.","5:17":"إن أخطأ أحد سهوا وارتكب إحدى نواهي الرب التي ينبغي ألا يرتكبها، يكون مذنبا ومسؤولا عن إثمه.","5:18":"وعليه أن يحضر إلى الكاهن ذبيحة إثم كبشا سليما تقدر أنت ثمنه، فيكفر الكاهن عما ارتكبه المخطئ من سهو على غير علم منه، فيغفر الرب له.","5:19":"إنه ذبيحة إثم، إذ قد ارتكب ذنبا في حق الرب».","6:1":"وقال الرب لموسى:","6:2":"«إن أخطأ أحد في حق الرب ورفض أن يرد لصاحبه وديعة أو أمانة أو مسلوبا، أو اغتصب منه شيئا،","6:3":"أو عثر على شيء مفقود وأنكره، أو حلف كاذبا على خطيئة ارتكبها فأثم،","6:4":"فعليه إذا أخطأ وأثم أن يرد ما سلبه أو اغتصبه أو استودعه، أو المفقود الذي عثر عليه،","6:5":"أو كل ما حلف عليه كاذبا، ويعوض قيمة الشيء مضافا إليه خمسه، وفي نفس اليوم يحضر إلى خيمة الاجتماع ذبيحة إثم:","6:6":"كبشا سليما تقدر أنت ثمنه ويأتي به إلى الكاهن،","6:7":"فيكفر عنه الكاهن أمام الرب، فيغفر الرب له ذنبه الذي ارتكبه».","6:8":"وقال الرب لموسى:","6:9":"«وهذا ما توصي به هرون وأبناءه بشأن شريعة تقدمة المحرقة: تترك المحرقة على الموقدة فوق المذبح كل الليل حتى الصباح، ونار المذبح تتوهج عليه.","6:10":"ثم يرتدي الكاهن ثوبه وسراويله الكتانية، وينظف المذبح من رماد المحرقة ويضعه إلى جانب المذبح.","6:11":"ثم يستبدل ملابسه بملابس أخرى، ويحمل هذا الرماد إلى خارج المخيم إلى مكان طاهر.","6:12":"وتظل النار في غضون ذلك تتوهج على المذبح لا تطفأ، لكي يشعل الكاهن بها حطبا كل صباح، ويرتب عليها المحرقة، ويوقد عليها شحم ذبيحة السلام اليومية.","6:13":"لتبق النار دائما متقدة على المذبح، لا تنطفئ أبدا.","6:14":"وهذه نصوص تعليمات تقدمة الدقيق التي يقربها أبناء هرون في حضرة الرب أمام المذبح:","6:15":"يأخذ الكاهن ملء قبضته من دقيق التقدمة وزيتها وكل اللبان الذي عليها، ويحرقها على المذبح للتذكار، فتكون ذبيحة رضى وسرور للرب.","6:16":"أما بقيتها فيأكله هرون وأبناؤه فطيرا في مكان مقدس في دار خيمة الاجتماع.","6:17":"يجب ألا يخبز بخميرة، فقد جعلته نصيب الكهنة من محرقاتي. إنها قدس أقداس كذبيحة الخطيئة وذبيحة الإثم.","6:18":"كل ذكر من أبناء هرون يأكل منها، فتكون لكم من محرقات الرب فريضة أبدية جيلا بعد جيل، ولا يمسها إلا من كان مقدسا».","6:19":"وقال الرب لموسى:","6:20":"«هذا ما يقربه هرون وأبناؤه للرب يوم تكريسهم كهنة: يقدمون للرب عشر الإيفة (نحو لترين ونصف اللتر) تقدمة دائمة من الدقيق، نصفها في الصباح ونصفها في المساء،","6:21":"معجونة بزيت عجنا جيدا ومخبوزة على صاج ومقطعة إلى فتات، فتقربونها للرب قربان رضى وسرور.","6:22":"وعلى كل أبناء الكهنة الذين يتكرسون كهنة عوضا عن والديهم أن يقدموا التقدمة نفسها فريضة أبدية للرب، وتحرق كلها.","6:23":"كل تقدمة كاهن تحرق بأجمعها، ولا يؤكل منها».","6:24":"وقال الرب لموسى:","6:25":"«قل لهرون وأبنائه: هذه نصوص تعليمات ذبيحة الخطيئة: تذبح ذبيحة الخطيئة في حضرة الرب، في نفس المكان الذي تذبح فيه المحرقة. إنها قدس أقداس.","6:26":"وعلى الكاهن الذي يقربها أن يأكلها في مكان مقدس، في دار خيمة الاجتماع.","6:27":"كل من مس لحمها يكون مقدسا. وإذا تناثر دمها على ثوب، تغسل الثوب في موضع مقدس.","6:28":"أما إناء الخزف الذي تطبخ فيه فيكسر. أما إن طبخت في إناء نحاسي فيجب أن يجلى ويغسل بماء.","6:29":"لا يأكل منها إلا الذكور من أولاد الكهنة لأنها قدس أقداس.","6:30":"كل ذبيحة يؤخذ من دمها إلى خيمة الاجتماع للتكفير في القدس لا يؤكل منها بل تحرق كلها بنار.","7:1":"وهذه نصوص تعليمات ذبيحة الإثم. إنها قدس أقداس.","7:2":"تذبحون ذبيحة الإثم في نفس الموضع الذي تذبحون فيه ذبيحة المحرقة، ويرش دمها على جوانب المذبح المحيطة به.","7:3":"ويقرب الكاهن منها كل شحمها: الألية وشحم الأعضاء الداخلية،","7:4":"والكليتين وشحمهما الذي على الخاصرتين وينزع المرارة مع الكليتين،","7:5":"ويحرقها الكاهن على المذبح وقودا للرب. إنها قربان إثم.","7:6":"كل ذكر من الكهنة يأكل منها في مكان مقدس، لأنها قدس أقداس.","7:7":"وشريعة ذبيحة الإثم مماثلة لذبيحة الخطيئة، إذ تكون من نصيب الكاهن الذي يكفر بها.","7:8":"والكاهن الذي يقرب محرقة إنسان يكون جلد المحرقة المقربة من نصيبه أيضا،","7:9":"وكذلك كل تقدمة دقيق مخبوز في فرن أو مقلاة أو على الصاج تكون للكاهن الذي يقربها","7:10":"وكل تقدمة دقيق بزيت أو جافة تكون من نصيب أبناء هرون، توزع عليهم بالتساوي.","7:11":"وهذه نصوص تعليمات ذبيحة السلام المقربة إلى الرب:","7:12":"إن قربها أحد لأجل الشكر، فليقدم معها كعكا غير مختمر معجونا بزيت، ورقاق فطير مدهونة بالزيت ودقيقا ملتوتا بزيت.","7:13":"فضلا عن أرغفة خبز مختمرة، يقربها مع ذبيحة شكر سلامته.","7:14":"وعليه أن يقدم واحدا من كل قربان يرفعه ويرجحه أمام الرب ويكون من نصيب الكاهن الذي يرش دم ذبيحة السلام.","7:15":"أما لحم ذبيحة شكر سلامته فيؤكل في نفس يوم تقديم الذبيحة كقربان، لا يبقي منه شيئا إلى الصباح.","7:16":"وإذا كانت ذبيحة تقدمته نذرا أو ذبيحة اختيارية أخرى، فإنها تؤكل في يوم تقديمها، وفي اليوم التالي يؤكل ما فضل منها،","7:17":"ويحرق كل ما يتبقى من الذبيحة لليوم الثالث.","7:18":"وكل من يأكل من ذبيحة سلامته في اليوم الثالث يكون مذنبا، لأنها تصبح غير مقبولة ولا يحسبها الله لمن قربها إذ تكون نجسة.","7:19":"وأي لحم يمس شيئا نجسا لا تأكلوا منه بل أحرقوه بالنار. لا يأكل من اللحم إلا من كان طاهرا.","7:20":"وكل نجس يأكل من لحم ذبيحة السلام المكرسة للرب يستأصل من بين شعبه","7:21":"والنفس التي تمس شيئا نجسا، سواء أكان نجاسة إنسان أم حيوان أم مكروها ما نجسا، ثم تتناول من لحم ذبيحة السلام، تستأصل تلك النفس من بين شعبها».","7:22":"وقال الرب لموسى:","7:23":"«أوص بني إسرائيل: لا تأكلوا كل شحم ثور أو كبش أو ماعز.","7:24":"أما شحم الحيوانات الميتة أو المفترسة فاستخدموه في أغراضكم المختلفة، إنما إياكم أن تأكلوا منه.","7:25":"من يأكل شحم بهائم المحرقات التي تقدمونها للرب يباد من بين شعبه.","7:26":"لا تأكلوا في جميع مساكنكم من دم الطير أو البهائم.","7:27":"من يأكل شيئا من الدم يباد من بين شعبه».","7:28":"وقال الرب لموسى:","7:29":"«أوص بني إسرائيل: من يقدم للرب ذبيحة سلامته عليه أن يحضرها بنفسه.","7:30":"هو نفسه يأتي بوقائد الرب. يأتي بالشحم والصدر. فيرجح الصدر أمام الرب،","7:31":"أما الشحم فيوقده الكاهن على المذبح، ويكون الصدر من نصيب هرون وبنيه.","7:32":"وتقدمون الساق اليمنى من ذبائح سلامتكم إلى الكاهن نصيبا له.","7:33":"فمن يقرب دم قربان السلام والشحم من أبناء هرون تكون الساق اليمنى نصيبا له،","7:34":"لأنني قد أخذت صدر الترجيح وساق ذبيحة سلام بني إسرائيل وأعطيتها لهرون الكاهن وأبنائه، فريضة دائمة، جيلا بعد جيل.","7:35":"هذا هو نصيب هرون ونصيب أبنائه من محرقات الرب، يوم تكريسهم ليكونوا كهنة للرب.","7:36":"وقد أمر الرب أن يعطى لهم يوم تكريسهم من بين بني إسرائيل، فريضة دائمة جيلا بعد جيل.","7:37":"تلك هي نصوص تعليمات شريعة المحرقة وتقدمة الدقيق وذبيحة الخطيئة وذبيحة الإثم، وذبيحة التكريس وذبيحة السلام،","7:38":"التي أوصى الرب بها موسى في جبل سيناء، عندما أمر بني إسرائيل بتقديم قرابينهم للرب في صحراء سيناء».","8:1":"وقال الرب لموسى:","8:2":"«أحضر هرون وأبناءه وثيابهم ودهن المسحة وثور ذبيحة الخطيئة والكبشين وسل الفطير،","8:3":"واجمع سائر بني إسرائيل عند مدخل خيمة الاجتماع».","8:4":"فنفذ موسى أمر الرب، فاجتمعت الجماعة عند مدخل خيمة الاجتماع،","8:5":"فقال لهم موسى: «هذا ما أمر الرب به».","8:6":"فقدم موسى هرون وأبناءه وغسلهم بماء،","8:7":"وألبس هرون القميص ونطقه بالحزام، وكساه بالجبة، ووضع عليه الرداء، ونطقه بحزام الرداء وشده به،","8:8":"وجعل عليه الصدرة، وثبت في الصدرة الأوريم والتميم،","8:9":"ووضع موسى على رأس هرون العمامة، وعلق عليها فوق الجبهة صفيحة الذهب، الإكليل المقدس، تماما كما أمره الرب.","8:10":"ثم أخذ موسى دهن المسحة ومسح المسكن وكل ما فيه وقدسه للرب.","8:11":"ثم رش من الدهن على المذبح سبع مرات، ومسح المذبح وجميع أوانيه وحوض الاغتسال وقاعدته لتقديسها،","8:12":"وصب من دهن المسحة على رأس هرون ومسحه تكريسا له.","8:13":"ثم أحضر موسى أبناء هرون وألبسهم أقمصة، ونطقهم بأحزمة، وعصب على رؤوسهم القلانس كما أمره الرب.","8:14":"ثم أتى بثور الخطيئة، فوضع هرون وأبناؤه أيديهم على رأسه،","8:15":"فذبحه موسى، وأخذ الدم ووضعه على قرون المذبح الأربعة، وعلى المذبح نفسه ليقدسه. ثم صب بقية الدم عند قاعدته، وكرسه تكفيرا عنه.","8:16":"وأخذ موسى شحم أعضاء الثور الداخلية، وكذلك المرارة والكليتين وشحمهما وأحرقها كلها على المذبح.","8:17":"وأما جلد الثور ولحمه وفرثه فأحرقها بنار خارج المخيم كما أمره الرب.","8:18":"ثم قدم كبش المحرقة، فوضع هرون وأبناؤه أيديهم على رأسه،","8:19":"فذبحه موسى ورش الدم على جوانب المذبح،","8:20":"وقطع الكبش إلى أجزائه، ثم أحرق الرأس والأجزاء والشحم.","8:21":"وأما أمعاؤه وأكارعه فقد غسلها بماء. وأحرق موسى كل الكبش على المذبح، فكان محرقة لرضى الرب وسروره. وقود هو للرب، تماما كما أمر الرب.","8:22":"ثم أحضر الكبش الثاني، كبش التكريس، فوضع هرون وأبناؤه أيديهم على رأسه،","8:23":"فذبحه موسى، وأخذ من دمه فوضعه على شحمة أذن هرون اليمنى، وعلى إبهام يده اليمنى وإبهام رجله اليمنى.","8:24":"ثم قدم موسى أبناء هرون ووضع من الدم على شحم آذانهم اليمنى، وعلى أباهم أيديهم اليمنى، وعلى أباهم أرجلهم اليمنى، ورش بقية الدم على جوانب المذبح.","8:25":"ثم أخذ شحم الألية وكل شحم الأعضاء الداخلية والمرارة والكليتين وشحمهما والساق اليمنى،","8:26":"وأخذ من سل الفطير الذي في حضرة الرب قرص فطير واحدا، وكعكة واحدة معجونة بزيت ورقاقة، ووضعها على الشحم وعلى الساق اليمنى،","8:27":"ووضعها جميعا على كفي هرون وأكف أبنائه ليرجحوها أمام الرب،","8:28":"ثم أخذها موسى عن أكفهم وأحرقها أمام الرب على المذبح فوق المحرقة، فكانت قربان تكريس لرضى الرب وسروره. إنها محرقة للرب.","8:29":"وتناول موسى صدر كبش التكريس ورجحه أمام الرب، فكان الصدر نصيب موسى كما أمره الرب.","8:30":"ثم أخذ موسى بعض دهن المسحة وبعض الدم الذي على المذبح، ورشها على هرون وثيابه، وعلى أبناء هرون وثيابهم، فقدسهم جميعا مع ملابسهم للرب.","8:31":"ثم قال لهرون وأبنائه: «اطبخوا اللحم عند مدخل خيمة الاجتماع، وكلوه هناك مع خبز سل التكريس، كما أوصيت ألا يأكله سوى هرون وأبنائه.","8:32":"وما تبقى من اللحم والخبز تحرقونه بنار.","8:33":"ولا تفارقوا مدخل خيمة الاجتماع سبعة أيام، إلى يوم اكتمال تكريسكم، لأن الرب يكرسكم سبعة أيام.","8:34":"إن ما جرى اليوم هو ما أمر به الرب تكفيرا عنكم.","8:35":"فامكثوا عند مدخل خيمة الاجتماع سبعة أيام، ليلا ونهارا، عاملين شعائر الرب، فلا تموتوا لأن هذا ما أوصيت به».","8:36":"فنفذ هرون وأبناؤه كل ما أمر به الرب على لسان موسى.","9:1":"وفي اليوم الثامن دعا موسى هرون وأبناءه وقادة بني إسرائيل،","9:2":"وقال لهرون: «أحضر ثورا لذبيحة الخطيئة وكبشا لمحرقة، على أن يكونا سليمين، وقدمهما في حضرة الرب.","9:3":"وقل لبني إسرائيل: خذوا تيسا من المعز لذبيحة الخطيئة، وثورا وخروفا حوليين سليمين لمحرقة،","9:4":"وثورا وكبشا لقربان سلام، للذبح في حضرة الرب، وتقدمة من دقيق معجون بالزيت، لأن الرب سيتجلى لكم اليوم».","9:5":"فجاءوا بما أمر به موسى إلى أمام خيمة الاجتماع، وتقدم كل الشعب ووقفوا في حضرة الرب،","9:6":"فقال موسى: «هذا ما أمركم به الرب لتعملوا، لكي يتجلى لكم مجد الرب».","9:7":"ثم قال موسى لهرون: «اقترب من المذبح وقدم ذبيحة خطيئتك ومحرقتك، وكفر عن نفسك وعن الشعب، ثم أحضر قربان الشعب وكفر عنهم كما أمر الرب».","9:8":"فاقترب هرون من المذبح، وقرب الثور ذبيحة خطيئة عن نفسه،","9:9":"وقدم له أبناؤه الدم فغمس إصبعه فيه ووضعه على قرون المذبح، ثم سكب بقية الدم عند قاعدته.","9:10":"وأحرق على المذبح شحم ذبيحة الخطيئة وكليتيها ومرارتها، كما أمر الرب موسى","9:11":"أما اللحم والجلد فقد أحرقهما خارج المخيم.","9:12":"ثم ذبح هرون كبش المحرقة، وقدم له أبناؤه الدم فرشه على جوانب المذبح.","9:13":"ثم ناولوه أجزاء لحم المحرقة، ورأسها فأحرقها على المذبح.","9:14":"وغسل الأمعاء والأكارع وأحرقها فوق المحرقة على المذبح.","9:15":"ثم قدم قربان الشعب. فأخذ تيس خطيئة الشعب، وذبحه وقدمه قربان خطيئة على مثال قربان الخطيئة الأول.","9:16":"ثم أحضر المحرقة وأصعدها حسب الشعائر المنصوصة.","9:17":"ورفع أيضا تقدمة الدقيق، فملأ قبضته منها وأحرقها على المذبح، بالإضافة إلى التقدمة الصباحية المعتادة.","9:18":"وكذلك ذبح الثور والكبش، ذبيحة سلام عن الشعب وأعطاه أبناؤه الدم فرشه على جوانب المذبح.","9:19":"وانتزع شحم الثور وألية الكبش وشحم الكليتين والمرارة منهما،","9:20":"ووضعوا الشحم على الصدرين، ثم أحرق الشحم على المذبح.","9:21":"وأما صدر كل منهما وساقه اليمنى فقد رجحها أمام الرب كما أمر موسى.","9:22":"ثم رفع هرون يديه نحو الشعب وباركهم. ولما انتهى من تقريب ذبيحة الخطيئة والمحرقة وذبيحة السلام، انحدر من عند المذبح.","9:23":"ودخل موسى وهرون إلى خيمة الاجتماع، وما لبثا أن خرجا وباركا الشعب، فتجلى مجد الرب للشعب كله.","9:24":"وخرجت نار من عند الرب أحرقت ذبيحة المحرقة والشحم الذي على المذبح. وعندما شهد الشعب هذا، هتفوا ساجدين بوجوه منحنية نحو الأرض.","10:1":"ثم وضع ناداب وأبيهو، ابنا هرون، في مجمرتيهما نارا غير مقدسة، وبخورا على خلاف ما أمرهما الرب، وقربا أمام الرب","10:2":"فاندلعت نار من عند الرب فالتهمتهما، فماتا في حضرة الرب.","10:3":"فقال موسى لهرون: «إليك ما قاله الرب: في القريبين مني أظهر قداستي، وأعلن مجدي أمام جميع الشعب». فصمت هرون.","10:4":"واستدعى موسى ميشائيل وألصافان ابني عزيئيل عم هرون وقال لهما: «تعاليا واحملا جثتي قريبيكما من أمام القدس إلى خارج المخيم».","10:5":"فتقدما ورفعاهما بقميصيهما إلى خارج المخيم، كما أمر موسى.","10:6":"وقال موسى لهرون وألعازار وإيثامار ابنيه: «لا تكشفوا رؤوسكم ولا تشقوا ثيابكم حدادا، لئلا تموتوا ويسخط الرب على كل الشعب. وأما بقية الشعب فليبكوا على اللذين أحرقهما الرب.","10:7":"وإياكم أن تخرجوا من باب خيمة الاجتماع لئلا تموتوا، لأن دهن مسحة الرب مازال عليكم». فنفذوا أمر موسى.","10:8":"وأمر الرب هرون:","10:9":"«لا تشرب أنت وأبناؤك خمرا مسكرا عند دخولكم لخدمتي في خيمة الاجتماع، لئلا تموتوا، وتكون هذه عليكم فريضة أبدية جيلا بعد جيل،","10:10":"لتميزوا بين المقدس والمحلل، النجس والطاهر،","10:11":"ولتعلموا شعب إسرائيل جميع الفرائض التي أمرت بها على لسان موسى».","10:12":"وقال موسى لهرون وابنيه الباقيين، ألعازار وإيثامار: «خذوا ما تبقى من تقدمة الدقيق المقربة إلى الرب وكلوها فطيرا إلى جوار المذبح، لأنها قدس أقداس.","10:13":"كلوها في مكان مقدس لأنها نصيبك ونصيب ابنيك من محرقات الرب، لأنني هكذا أمرت.","10:14":"وأما الصدر المرجح والساق اليمنى المقدمة، فكلها أنت وبنوك وبناتك في مكان طاهر، لأنها نصيبك ونصيب أبنائك من ذبائح سلام شعب إسرائيل.","10:15":"عندما يأتي الشعب بساق التقدمة وصدر الترجيح ووقائد الشحم لترجيحها أمام الرب، يصبحان من نصيبك ونصيب أبنائك، فريضة أبدية جيلا بعد جيل».","10:16":"وبحث موسى عن تيس الخطيئة فوجده قد احترق فاغتاظ من ألعازار وإيثامار ابني هرون الباقيين وقال:","10:17":"«لماذا لم تأكلا ذبيحة الخطيئة في المكان المقدس؟ إنها قدس أقداس، وهبها الرب لكما لتحملا إثم الجماعة، تكفيرا عنهم أمام الرب.","10:18":"مادام دمها لم يؤخذ إلى داخل القدس، كان عليكما أن تأكلاها في القدس كما أوصيت».","10:19":"فقال هرون لموسى: «لقد قربا اليوم ذبيحة خطيئتهما ومحرقتهما في حضرة الرب، فلو أكلنا ذبيحة الخطيئة في مثل هذا اليوم، وقد أصابنا ما أصابنا، فهل كان الرب يرضى عنا؟»","10:20":"فاقتنع موسى بهذا الجواب.","11:1":"وأمر الرب موسى وهرون:","11:2":"«أوصيا بني إسرائيل: هذه هي الحيوانات التي تأكلونها من جميع بهائم الأرض:","11:3":"تأكلون كل حيوان مشقوق الظلف ومجتر،","11:4":"أما الحيوانات المجترة فقط، أو المشقوقة الظلف فقط، فلا تأكلوا منها، فالجمل غير طاهر لكم لأنه مجتر ولكنه غير مشقوق الظلف،","11:5":"وكذلك الوبر نجس لكم لأنه مجتر ولكنه غير مشقوق الظلف،","11:6":"أما الأرنب فإنه مجتر ولكنه غير مشقوق الظلف، لذلك هو نجس لكم،","11:7":"والخنزير أيضا نجس لكم لأنه مشقوق الظلف ولكنه غير مجتر.","11:8":"لا تأكلوا من لحمها ولا تلمسوا جثثها لأنها نجسة لكم.","11:9":"أما ما يعيش في الماء فتأكلون منه كل ما له زعانف وقشور، سواء كان يعيش في البحار أم الأنهار، فهذه تأكلونها.","11:10":"ولكن إياكم أن تأكلوا الحيوانات المائية التي ليس لها زعانف أو قشور، سواء كانت تعيش في الأنهار أو البحار، أو الزواحف في المياه، أو كل نفس حية فيها، فهذه كلها محظورة عليكم.","11:11":"فلا تأكلوا من لحمها وامقتوا جثثها.","11:12":"كل حيوان مائي خال من الزعانف والقشور يكون محظورا عليكم.","11:13":"ومن الطيور التي يحظر عليكم أكلها لأنها ممقوتة: النسر والأنوق والصقر،","11:14":"والحدأة والباشق على مختلف أصنافه،","11:15":"وكل أجناس الغربان،","11:16":"والنعامة والظليم والسأف وكل أنواع طير الباز،","11:17":"والبومة والغواص والكركي،","11:18":"والبجع والقوق والرخم،","11:19":"واللقلق والببغاء على اختلاف أجناسها، والهدهد والخفاش.","11:20":"وكذلك تحظر عليكم كل حشرة مجنحة ذات أربع أرجل.","11:21":"ولكن كلوا من بين الكائنات المجنحة التي تمشي على أربع ما له ساقان أطول من يديه يقفز بهما على الأرض.","11:22":"فمن هذه الكائنات تأكلون: كل أنواع الجراد، وجميع أصناف الدبا والحرجوان على مختلف أجناسه والجندب بأنواعه","11:23":"أما سائر دبيب الطير ذوات الأربع الأرجل فهو محظور عليكم،","11:24":"فإنها تنجسكم، وكل من يلمس جثثها يتنجس حتى المساء.","11:25":"وعلى كل من حمل جثثها أن يغسل ثيابه ويكون نجسا حتى المساء،","11:26":"وكذلك جميع البهائم ذوات الأظلاف غير المشقوقة وغير المجترة تكون نجسة لكم، وكل من يلمسها يتنجس.","11:27":"وأيضا كل حيوان يمشي على كفوفه من جميع الحيوانات ذوات الأربع الأرجل، فهو نجس لكم، وكل من يمس جثثها يكون نجسا حتى المساء،","11:28":"ومن يحمل جثثها يغسل ثيابه ويكون نجسا إلى المساء. جميعها محظورة عليكم.","11:29":"أما الحيوانات الدابة حولكم فوق الأرض والمحظورة عليكم لنجاستها فهي: ابن عرس والفأر والضب على مختلف أجناسه،","11:30":"والحرذون والورل والوزغة والعظاية والحرباء.","11:31":"هذه هي الحيوانات النجسة لكم من جميع الحيوانات الدابة. كل من لمسها يكون نجسا حتى المساء.","11:32":"إن وقعت جثة أحد هذه الحيوانات على شيء فإنه يتنجس، سواء أكان آنية من خشب أم قماش أم جلد أم مسح، أم أي شيء يستخدم في عمل ما. يوضع في ماء ويكون نجسا إلى المساء، ثم يطهر.","11:33":"أما إن وقعت جثة أحدها في إناء خزفي، فإن ما في الإناء يتنجس، وأما الإناء فيكسر.","11:34":"وأي طعام يؤكل استخدم فيه ماء من هذا الإناء يكون نجسا. وكذلك يكون ماؤه الذي يشرب أيضا.","11:35":"وإذا سقطت جثة أحد هذه الحيوانات في التنور أو الموقد، فإنه يهدم، لأنه نجس وأنتم به تتنجسون.","11:36":"أما إن سقطت في نبع أو بئر حيث يجتمع الماء، فإنهما تظلان طاهرتين. لكن كل من لمس جثتها يكون نجسا.","11:37":"وإذا وقعت جثة واحدة منها على حبوب يبذرونها في حقل، فإنها تبقى طاهرة.","11:38":"لكن إن كانت الحبوب مبتلة بماء وسقطت الجثة عليها، فإن الحبوب المبتلة تصبح نجسة لكم.","11:39":"إن مات حيوان لا يحل لكم أكله، ولمس أحد جثته، فاللامس يكون نجسا حتى المساء.","11:40":"وعلى من أكل من جثته أو حملها أن يغسل ثيابه ويكون نجسا إلى المساء.","11:41":"ويحظر عليكم الأكل من الحيوانات الزاحفة،","11:42":"سواء كانت تزحف على بطنها أو تدب على أربع أو أكثر فإنها محظورة عليكم، فلا تأكلوا منها.","11:43":"لا تدنسوا أنفسكم بالحيوانات الدابة هذه، ولا تتنجسوا بها. كونوا طاهرين.","11:44":"أنا الرب إلهكم، فكرسوا أنفسكم وتقدسوا، لأني أنا قدوس، ولا تنجسوا أنفسكم بشيء من الدبيب المتحرك على الأرض.","11:45":"لأني أنا الرب الذي أخرجكم من ديار مصر لأكون لكم إلها. فكونوا قديسين لأني أنا قدوس.","11:46":"هذه هي الشرائع الخاصة بالحيوانات والطيور والحيوانات المائية والزواحف،","11:47":"لكي تميزوا بين النجس والطاهر، وبين الحيوانات التي تؤكل والحيوانات المحظور أكلها».","12:1":"وقال الرب لموسى:","12:2":"«أوص بني إسرائيل: إذا حملت امرأة وولدت ذكرا، تظل الأم في حالة نجاسة سبعة أيام، كما في أيام فترة الحيض.","12:3":"وفي اليوم الثامن يجرى ختان الطفل.","12:4":"وعلى المرأة أن تبقى ثلاثة وثلاثين يوما أخرى إلى أن تطهر من نزيفها، فلا تمس أي شيء مقدس، ولا تحضر إلى المقدس، إلى أن تتم أيام تطهيرها.","12:5":"وإن ولدت أنثى فإنها تظل في حالة نجاسة مدة أسبوعين كما في فترة الحيض، وتبقى ستة وستين يوما حتى تتطهر من نزيفها.","12:6":"وعندما تكتمل أيام تطهيرها سواء ولدت ذكرا أم أنثى، تحضر حملا حوليا تقدمه محرقة، وكذلك فرخ حمامة أو يمامة ذبيحة خطيئة، إلى مدخل خيمة الاجتماع إلى الكاهن،","12:7":"فيقربها أمام الرب ويكفر عنها، فتتطهر من نزيفها. هذه هي الشريعة الخاصة بكل أم بعد الولادة.","12:8":"وإن كانت الأم أفقر من أن تقدم حملا، فلتأت بيمامتين أو فرخي حمام، فيكون أحدهما محرقة والآخر ذبيحة خطيئة، فيكفر بهما عنها الكاهن وتطهر».","13:1":"وقال الرب لموسى وهرون:","13:2":"«إذا أصيب جلد إنسان بورم أو قوباء أو لمعة، يمكن أن تتحول في جلده إلى داء البرص، فليؤخذ إلى هرون أو إلى أحد أبنائه الكهنة ليعاينه.","13:3":"فإن وجد الكاهن أن الشعر في موضع الداء قد ابيض، وأن مكمن الداء غائر عن سطح الجلد المحيط به، فالداء يكون ضربة البرص. فيعلن الكاهن أنه مصاب بمرض البرص النجس.","13:4":"وإن لم تكن البقعة البيضاء غائرة عن سطح الجلد، ولم يكن الشعر الموجود فيها قد ابيض، يحجز الكاهن المريض سبعة أيام،","13:5":"ثم يفحصه بعد ذلك، فإن وجد أن البقعة لم تتسع وتمتد، يحجزه الكاهن سبعة أيام أخرى،","13:6":"ويعاينه في اليوم السابع ثانية. فإذا وجد أن الضربة داكنة اللون والبقعة لم تتسع وتمتد، يحكم بسلامته. إنها قوباء. وعليه فقط أن يغسل ثيابه فيعتبر طاهرا.","13:7":"لكن إن امتدت البقعة في الجلد بعد معاينة الكاهن له لتطهيره، يعرض على الكاهن مرة أخرى،","13:8":"فإن وجد الكاهن بعد فحصه أن البقعة قد امتدت واتسعت، يعلن الكاهن نجاسته لإصابته بمرض البرص.","13:9":"إذا كان إنسان مصابا بداء البرص تعرضونه على الكاهن،","13:10":"فإن وجد الكاهن بعد فحصه أن في الجلد ورما أبيض، ابيض فيه الشعر وبدت فيه قرحة،","13:11":"فيكون هذا مرض برص مزمن أصاب جلده. ويعلن الكاهن لذلك نجاسته، ولا يحجزه لثبوت الداء فيه.","13:12":"لكن إن كان البرص قد انتشر في جلد البدن كله، وغطى المصاب من رأسه إلى قدميه،","13:13":"يعيد الكاهن فحصه. فإذا وجد أن البرص غطى الجسم كله يعلن طهارته، لأن جلده كله قد استحال إلى اللون الأبيض.","13:14":"لكن حين يرى فيه قرحة، يحكم بنجاسة المريض،","13:15":"ثم يعيد فحصه. فإذا وجد القرحة في الجلد المصاب، يعلن نجاسة المريض، لأن القرحة نجسة، وهي علامة البرص.","13:16":"ثم إن عاد لون القرحة وابيض يعرض نفسه على الكاهن،","13:17":"فإن فحصها الكاهن ووجد أن البقعة قد تحولت إلى بيضاء، يعلن طهارة المصاب. إنه طاهر.","13:18":"إن كان في جلد إنسان دمل تم شفاؤه،","13:19":"ثم تخلف عنه ورم أبيض أو بقعة لامعة بيضاء ضاربة إلى الحمرة، فليعرض على الكاهن","13:20":"فإن وجد الكاهن أن موضع الداء غائر عن سطح باقي الجلد، وقد ابيض الشعر فيه، يعلن نجاسته، لأنه داء برص أفرخ في الدمل.","13:21":"ولكن إن عاينه الكاهن فوجد أن موضع الداء خال من الشعر الأبيض، وأنه يستوي مع سطح باقي الجلد، وأن لونه داكن، يحجز المصاب سبعة أيام.","13:22":"فإن امتد واتسع في الجلد يحكم الكاهن بنجاسته، لأنه مصاب بالداء.","13:23":"ولكن إن بقيت البقعة اللامعة كما هي، ولم تتسع وتمتد، تكون مجرد أثر للدمل، فيعلن طهارة المصاب.","13:24":"إن احترق جلد إنسان فابيض موضع الحرق، أو صار أبيض ضاربا إلى الحمرة،","13:25":"وفحص الكاهن البقعة اللامعة فوجد أن شعرها قد ابيض، وبدت غائرة عن سطح باقي الجلد، يكون ذلك برصا أفرخ في موضع الحرق، فيحكم بنجاسته.","13:26":"ولكن إن فحصها الكاهن ولم يجد في البقعة شعرا أبيض، وأنها تستوي مع سطح باقي الجلد، وأن لونها داكن يحجزه أسبوعا،","13:27":"ثم يعيد فحصه في اليوم السابع. فإن وجد أنها امتدت في الجلد، يعلن نجاسته لأنه مصاب بالبرص","13:28":"لكن إن بقيت البقعة اللامعة على حالها ولم تمتد في الجلد، واكمد لونها، فهي مجرد أثر الحرق وليست برصا، ويعلن الكاهن طهارة المصاب.","13:29":"إذا أصيب رجل أو امرأة بقرحة في الرأس أو في الذقن،","13:30":"وعاين الكاهن الإصابة فوجدها غائرة عن سطح باقي الجلد، وفيها شعر أشقر دقيق، يحكم بنجاسة المصاب لأنها قرع، برص الرأس أو الذقن","13:31":"لكن إذا وجد الكاهن بعد فحصه إصابة القرع أنها ليست غائرة عن سطح باقي الجلد، وأنها خالية من الشعر الأسود، يحجز الكاهن المصاب بالقرع سبعة أيام،","13:32":"ثم يعيد الفحص في اليوم السابع. فإن وجد أنها لم تمتد وأنها خالية من الشعر الأشقر وأنها تستوي مع سطح باقي الجلد،","13:33":"يحلق المصاب شعره باستثناء شعر البقعة المصابة. ويحجزه الكاهن سبعة أيام أخرى","13:34":"فإن وجد الكاهن في اليوم السابع أن الإصابة لم تمتد في جلد المريض، وأنها تستوي مع سطح باقي الجلد، يحكم بطهارته. وعليه فقط أن يغسل ثيابه فيكون طاهرا.","13:35":"لكن إن امتد القرع في الجلد بعد عرضه على الكاهن والحكم بطهارته،","13:36":"يفحصه الكاهن ثانية. فإن رأى أن الإصابة قد امتدت في الجلد، لا يحتاج الكاهن أن يبحث عن شعر أشقر، لأن المصاب مريض بداء البرص.","13:37":"لكن إن وجد الكاهن أن الإصابة توقفت ولم تمتد، وقد نبت فيها شعر أسود، فتلك علامة شفائه. ويحكم بطهارته.","13:38":"وإن ظهرت في جلد رجل أو امرأة بقع لامعة بيضاء،","13:39":"وفحصها الكاهن، وإذا بها كامدة اللون بيضاء، يكون ذلك بهق قد انتشر في الجلد، والمصاب يكون طاهرا.","13:40":"وإذا سقط شعر إنسان فهو أقرع، ويكون طاهرا.","13:41":"وإن سقط الشعر من مقدمة رأسه فهو أصلع، ويكون طاهرا.","13:42":"ولكن إن ظهر في القرعة أو الصلعة قرحة بيضاء ضاربة إلى الحمرة، يكون هذا برص قد أفرخ في قرعته أو صلعته،","13:43":"فيفحصه الكاهن. فإذا وجد أن الورم في قرعته أو صلعته أبيض ضارب إلى الحمرة، مماثل للبرص في جلد البدن،","13:44":"يكون آنئذ أبرص نجسا مصابا برأسه، ويحكم الكاهن بنجاسته.","13:45":"وعلى المصاب بداء البرص أن يشق ثيابه ويكشف رأسه ويغطي شاربيه، وينادي: «نجس! نجس!».","13:46":"ويظل طول فترة مرضه نجسا يقيم وحده خارج المخيم معزولا.","13:47":"وإذا بدا داء البرص المعدي، في ثوب صوف أو كتان","13:48":"أو في قطعة قماش منسوجة أو محيكة من صوف أو كتان، أو في جلد، أو في كل مصنوع من جلد،","13:49":"وكانت إصابة الثوب أو الجلد أو قطعة القماش المنسوجة أو المحيكة، أو في شيء مصنوع من جلد، ضاربة إلى الحمرة أو الخضرة، فإنها إصابة برص تعرض على الكاهن.","13:50":"فيفحص الإصابة ويحجز الشيء المصاب سبعة أيام،","13:51":"ثم يفحصها في اليوم السابع. فإن وجدها قد امتدت في الثوب أو قطعة القماش، أو في الجلد أو في كل ما يصنع من جلد، ويستخدم في عمل ما، فإن الإصابة تكون برصا معديا وتكون نجسة.","13:52":"فيحرق الكاهن بالنار الثوب أو قطعة قماش الصوف أو الكتان أو متاع الجلد المصاب، لأنه داء معد.","13:53":"لكن إن وجد الكاهن أن الإصابة لم تمتد في الثوب أو في قطعة القماش المنسوجة أو المحيكة أو في متاع الجلد،","13:54":"يأمر بغسل الشيء ويحجزه سبعة أيام أخرى.","13:55":"فإن رأى الكاهن أن لون البقعة في الشيء المصاب لم يتغير، ولا اتسعت البقعة فيه، يأمر بحرقه فهو نجس لأنه انتشر في ظاهر المتاع وفي باطنه.","13:56":"ولكن إن وجد الكاهن، بعد فحص الشيء المصاب، أن البقعة قد كمد لونها بعد غسلها، فلينتزعها من الثوب أو الجلد أو قطعة القماش المنسوجة أو المحيكة.","13:57":"ثم إن عادت البقعة فظهرت ثانية في الثوب أو في القماش المنسوج أو المحيك أو متاع الجلد، تكون الإصابة معدية. ويجب إحراق الشيء المصاب بالنار.","13:58":"وأما الثوب أو بطانته المنسوجة أو المحيكة، أو متاع الجلد الذي يتم غسله وتزول منه البقعة، فيغسل ثانية ويطهر.","13:59":"هذه هي نصوص التعليمات المتعلقة بإصابة البرص في الصوف أو الكتان في البطانة المنسوجة أو المحيكة، أو في كل متاع جلدي، وبمقتضاها تحكمون على طهارتها أو نجاستها».","14:1":"وقال الرب لموسى:","14:2":"«هذه هي نصوص التعليمات المتعلقة بالأبرص المطهر من برصه. يحضرونه إلى الكاهن في يوم شفائه،","14:3":"فيخرج الكاهن إلى خارج المخيم ليفحصه فإن وجد أنه قد برئ من داء البرص،","14:4":"يأمر الكاهن أن يؤتى للأبرص المبرء بعصفورين حيين طاهرين، وخشب أرز، وخيط أحمر وباقة زوفا.","14:5":"فيأمر الكاهن بذبح عصفور واحد في إناء خزفي فوق ماء جار.","14:6":"أما العصفور الحي فيأخذه مع خشب الأرز والخيط الأحمر والزوفا، ويغمسها جميعا في دم العصفور المذبوح فوق الماء الجاري،","14:7":"ثم يرش على المتطهر من البرص سبع مرات فيطهره، ثم يطلق العصفور الحي على وجه الصحراء.","14:8":"ويغسل المتطهر ثيابه، ويحلق كل رأسه، ويستحم بماء فيطهر، ثم يدخل المخيم. إلا أنه يقيم خارج خيمته سبعة أيام.","14:9":"وفي اليوم السابع يحلق ما نما من شعر رأسه، وكذلك لحيته وحواجبه، ويغسل ثيابه ويستحم بماء فيصبح طاهرا.","14:10":"وفي اليوم الثامن يحضر إلى الكاهن كبشين صحيحين، ونعجة حولية سليمة وثلاثة أعشار (نحو سبعة لترات) من الدقيق المعجون بزيت ولج (نحو ثلث لتر) زيت.","14:11":"فيوقف الكاهن القائم بالتطهير الأبرص المتطهر وتقدمته عند مدخل خيمة الاجتماع،","14:12":"ثم يأخذ أحد الكبشين والزيت ويرجحهما في حضرة الرب، ويقربهما ذبيحة إثم.","14:13":"ثم يذبح الكبش في الجانب الشمالي من المذبح حيث يذبح قربان الخطيئة والمحرقة في المكان المقدس، لأن ذبيحة الإثم هي كذبيحة الخطيئة، تكون من نصيب الكاهن. إنها قدس أقداس.","14:14":"ويضع الكاهن من دم ذبيحة الإثم على شحمة أذن المتطهر اليمنى، وعلى إبهام يده اليمنى، وإبهام قدمه اليمنى،","14:15":"ثم يأخذ الكاهن الزيت ويصب في كفه اليسرى،","14:16":"ويغمس إصبعه اليمنى في الزيت المصبوب في يده اليسرى، ويرش منه سبع مرات أمام الرب.","14:17":"ويضع الكاهن من الزيت الباقي في كفه على شحمة أذن المتطهر اليمنى وعلى إبهام يده اليمنى وإبهام رجله اليمنى فوق دم ذبيحة الإثم،","14:18":"ويسكب الكاهن ما تبقى من زيت في كفه على رأس المتطهر، ويكفر عنه أمام الرب.","14:19":"ثم يقدم الكاهن ذبيحة الخطيئة تكفيرا عن المتطهر من برصه ثم يذبح المحرقة","14:20":"ويصعد الكاهن المحرقة والتقدمة على المذبح تكفيرا عنه، فيصبح طاهرا.","14:21":"أما إذا كان المتطهر فقيرا وعاجزا عن ذلك، يحضر كبشا واحدا ذبيحة إثم تكفيرا عنه، وعشرا (نحو لترين ونصف اللتر) من دقيق معجون بزيت كتقدمة، ولج (نحو ثلث لتر) زيت،","14:22":"ويمامتين أو فرخي حمام، حسب قدرته، فيكون الواحد ذبيحة خطيئة والآخر محرقة.","14:23":"يحضر هذه كلها في اليوم الثامن إلى الكاهن عند مدخل خيمة الاجتماع لفريضة تطهيره،","14:24":"فيأخذ الكاهن كبش الإثم والزيت ويرجحهما أمام الرب،","14:25":"ثم يذبح كبش الإثم ويأخذ من دمه ويضع منه على شحمة أذن المتطهر اليمنى، وعلى إبهامي يده اليمنى ورجله اليمنى.","14:26":"ويصب الكاهن في كفه اليسرى زيتا،","14:27":"ويرش منه بإصبعه اليمنى سبع مرات أمام الرب.","14:28":"وكذلك يضع الكاهن من الزيت الذي في كفه على شحمة أذن المتطهر اليمنى وعلى إبهامي يده اليمنى ورجله اليمنى فوق موضع دم ذبيحة الإثم.","14:29":"ويسكب ما تبقى من زيت في كفه على رأس المتطهر، تكفيرا عنه أمام الرب.","14:30":"ثم يقدم الكاهن اليمامتين أو فرخي الحمام، بحسب قدرة المتطهر،","14:31":"فيقرب إحداهما ذبيحة خطيئة والأخرى محرقة مع التقدمة، تكفيرا عن المتطهر أمام الرب.","14:32":"هذه هي نصوص التعليمات المتعلقة بالأبرص المتطهر الفقير».","14:33":"وقال الرب لموسى:","14:34":"«عندما تدخلون أرض كنعان التي وهبتها لكم ملكا، وجعلت البرص المعدي يتفشى في أحد البيوت في الأرض التي امتلكتم،","14:35":"يأتي صاحب البيت ويخبر الكاهن أن داء البرص قد يكون متفشيا بالبيت،","14:36":"فيأمر الكاهن بإخلاء البيت قبل أن يدخل إليه لئلا يتنجس كل ما في البيت، ثم يدخل الكاهن البيت ليفحصه.","14:37":"فإذا عاين الإصابة ووجد أن في حيطان البيت نقرا لونها ضارب إلى الخضرة أو إلى الحمرة، وبدا منظرها غائرا في الحيطان،","14:38":"يغادر الكاهن البيت ويغلق بابه سبعة أيام.","14:39":"فإذا رجع في اليوم السابع وفحصه، ووجد أن الإصابة قد امتدت في حيطان البيت،","14:40":"يأمر الكاهن بقلع الحجارة المصابة وطرحها خارج المدينة في مكان نجس،","14:41":"وتكشط حيطان البيت الداخلية، ويطرحون التراب المكشوط خارج المدينة في مكان نجس","14:42":"ثم يأتون بحجارة أخرى يضعونها مكان الحجارة المقتلعة ويعيدون تطيين البيت من جديد.","14:43":"فإن رجعت الإصابة وانتشرت في البيت بعد قلع الحجارة وكشط الحيطان وتطيينها،","14:44":"ووجد الكاهن ذلك، تكون هذه إصابة داء برص معد في البيت، إنه نجس.","14:45":"فيتم هدم البيت بما فيه من حجارة وأخشاب وتراب، وتنقل كلها إلى خارج المدينة إلى مكان نجس.","14:46":"ومن دخل البيت في أثناء غلقه يكون نجسا إلى المساء.","14:47":"وعلى كل من نام فيه أو أكل، أن يغسل ثيابه.","14:48":"لكن إن وجد الكاهن أن الإصابة لم تنتشر في البيت بعد تطيينه، يطهره الكاهن، لأن داء البرص قد زال منه.","14:49":"فيحضر لتطهير البيت عصفورين وخشب أرز وخيطا أحمر وزوفا،","14:50":"فيذبح أحد العصفورين في إناء خزفي فوق ماء جار،","14:51":"ويغمس خشب الأرز والزوفا والخيط الأحمر والعصفور الحي بدم العصفور المذبوح وبالماء الجاري، ويرش البيت سبع مرات،","14:52":"ويطهر البيت بدم العصفور وبالماء الجاري وبالعصفور الحي وبخشب الأرز والزوفا والخيط الأحمر.","14:53":"ثم يطلق العصفور الحي إلى خارج المدينة على وجه الصحراء، تكفيرا عن البيت، فيصبح طاهرا.","14:54":"هذه هي نصوص التعليمات المتعلقة بكل أنواع إصابات البرص والقرع،","14:55":"التي منها برص الثوب والبيت،","14:56":"والورم الجلدي والقوباء والبقعة اللامعة.","14:57":"وهذه التعليمات هي للتمييز بين ما هو نجس وما هو طاهر في حالة الإصابة بما يبدو أنه داء البرص».","15:1":"وقال الرب لموسى وهرون:","15:2":"«أوصيا بني إسرائيل: كل رجل جسده مصاب بالسيلان فهو نجس،","15:3":"ونجاسته في سيلانه، سواء أفرز البدن السيلان أم احتبسه، فذلك يكون نجاسته،","15:4":"كل ما ينام عليه المصاب بالسيلان من فراش أو يجلس عليه من متاع يكون نجسا،","15:5":"وعلى من لمس فراشه أن يغسل ثيابه ويستحم، ويكون نجسا إلى المساء.","15:6":"ومن يجلس على متاع جلس عليه المصاب بالسيلان يغسل ثيابه ويستحم بماء، ويكون نجسا إلى المساء.","15:7":"ومن يمس جسد المصاب بالسيلان يغسل ثيابه ويستحم بماء، ويكون نجسا إلى المساء.","15:8":"وإن بصق المصاب بالسيلان على شخص طاهر، فعلى الطاهر أن يغسل ثيابه ويستحم بماء، ويكون نجسا إلى المساء","15:9":"كل ما يمتطيه المصاب بالسيلان يصبح نجسا.","15:10":"وكل من يلمس شيئا كان تحت المصاب، أو حمله يغسل ثيابه ويستحم بماء، ويكون نجسا إلى المساء.","15:11":"وعلى كل شخص يمسه المصاب من غير أن يكون قد غسل يديه بماء، أن يغسل ثيابه بماء ويستحم بماء، ويكون نجسا إلى المساء.","15:12":"وأي إناء خزفي يلمسه المصاب يكسر. أما إناء الخشب فيغسل بماء.","15:13":"وإذا برىء المصاب بالسيلان من دائه فليمكث سبعة أيام لطهره، ويغسل ثيابه ويستحم بماء جار، فيطهر،","15:14":"وفي اليوم الثامن يأخذ لنفسه يمامتين أو فرخي حمام ويأتي أمام الرب إلى مدخل خيمة الاجتماع ويعطيهما للكاهن،","15:15":"فيقدم الكاهن أحدهما ذبيحة خطيئة والآخر محرقة. ويكفر الكاهن عن المصاب بالسيلان أمام الرب.","15:16":"وإذا أفرز رجل سائله المنوي، يغسل كل جسده بماء ويصبح نجسا إلى المساء.","15:17":"وكل ما يقع عليه السائل المنوي من ثياب أو جلد يغسل بماء ويكون نجسا إلى المساء.","15:18":"وإذا عاشر رجل زوجته يستحمان كلاهما بماء ويكونان نجسين إلى المساء.","15:19":"وإذا حاضت المرأة فسبعة أيام تكون في طمثها، وكل من يلمسها يكون نجسا إلى المساء.","15:20":"كل ما تنام عليه في أثناء حيضها أو تجلس عليه يكون نجسا،","15:21":"وكل من يلمس فراشها يغسل ثيابه ويستحم بماء ويكون نجسا إلى المساء.","15:22":"وكل من مس متاعا تجلس عليه، يغسل ثيابه ويستحم بماء، ويكون نجسا إلى المساء.","15:23":"وكل من يلمس شيئا كان موجودا على الفراش أو على المتاع الذي تجلس عليه يكون نجسا إلى المساء.","15:24":"وإن عاشرها رجل وأصابه شيء من طمثها، يكون نجسا سبعة أيام. وكل فراش ينام عليه يصبح نجسا.","15:25":"إذا نزف دم امرأة فترة طويلة في غير أوان طمثها، أو استمر الحيض بعد موعده، تكون كل أيام نزفها نجسة كما في أثناء طمثها.","15:26":"كل ما تنام عليه في أثناء نزفها يكون نجسا كفراش طمثها، وكل ما تجلس عليه من متاع يكون نجسا كنجاسة طمثها.","15:27":"وأي شخص يلمسهن يكون نجسا، فيغسل ثيابه ويستحم بماء، ويكون نجسا إلى المساء","15:28":"وإذا برئت من نزفها فلتمكث سبعة أيام ثم تطهر،","15:29":"وفي اليوم الثامن تجيء بيمامتين أو فرخي حمام إلى الكاهن إلى مدخل خيمة الاجتماع،","15:30":"فيقدم الكاهن أحدهما ذبيحة خطيئة، والآخر محرقة. ويكفر الكاهن عنها في حضرة الرب من نزف نجاستها.","15:31":"وبهذا تحفظان بني إسرائيل مما ينجسهم، لئلا يموتوا في نجاستهم إن دنسوا مسكني الذي في وسطهم.","15:32":"هذه هي نصوص التعليمات بشأن المصاب بالسيلان، أو من يفرز سائله المنوي فيتنجس به،","15:33":"والمرأة الحائض، والرجل أو المرأة المصاب بالسيلان، والرجل الذي عاشر امرأة حائضا».","16:1":"وقال الرب لموسى بعد وفاة ابني هرون، عندما اقتربا أمام الرب فماتا:","16:2":"«كلم أخاك هرون وحذره من الدخول في كل وقت إلى قدس الأقداس، وراء الحجاب أمام غطاء التابوت، لئلا يموت، لأنني أتجلى في السحاب على الغطاء.","16:3":"بهذا يدخل هرون إلى القدس: يأتي بثور لذبيحة خطيئة وكبش لمحرقة،","16:4":"وعليه أن يلبس قميص كتان مقدسا، ويرتدي فوق جسده سراويل كتان، ويتنطق بحزام كتان، ويتعمم بعمامة كتان، بعد أن يغتسل بماء. إنها ثياب مقدسة.","16:5":"يأخذ من شعب إسرائيل تيسين من المعز لذبيحة الخطيئة، وكبشا واحدا ليكون محرقة،","16:6":"فيقرب هرون ثور الخطيئة تكفيرا عن نفسه وعن أسرته،","16:7":"ثم يأخذ التيسين ويقدمهما أمام الرب عند مدخل خيمة الاجتماع،","16:8":"ويلقي عليهما قرعتين: قرعة للرب وقرعة لعزازيل (كبش الفداء).","16:9":"ويقرب هرون التيس الذي وقعت عليه قرعة الرب ويصعده ذبيحة خطيئة،","16:10":"وأما التيس الذي وقعت عليه قرعة عزازيل، فيوقفه حيا أمام الرب ليكفر عنه، ثم يطلقه إلى الصحراء، فهو كبش فداء.","16:11":"وبعد أن يقدم هرون ثور الخطيئة تكفيرا عن نفسه وعن أسرته ويذبحه،","16:12":"يملأ المجمرة بجمر نار من على المذبح من أمام الرب، ويأخذ ملء قبضته من البخور العطر الدقيق ويدخل بهما إلى ما وراء الحجاب.","16:13":"ويضع البخور على النار في حضرة الرب، فتغشي سحابة البخور غطاء التابوت، فلا يموت.","16:14":"ثم يأخذ بعض دم الثور ويرش بإصبعه على وجه الجزء الشرقي من غطاء التابوت، كما يرش من الدم بإصبعه سبع مرات أمام الغطاء.","16:15":"ويذبح تيس الخطيئة المقدم من الشعب، ويدخل بدمه إلى ما وراء الحجاب، ويرش من دمه كما رش من دم الثور على الغطاء وأمامه،","16:16":"فيكفر عن القدس من نجاسات بني إسرائيل وسيئاتهم وسائر خطاياهم. ومثل ذلك يفعل لخيمة الاجتماع القائمة في وسطهم، محاطة بنجاساتهم.","16:17":"ولا يكن أحد في خيمة الاجتماع عند دخول هرون إلى قدس الأقداس للتكفير عن نفسه وعن أسرته وعن كل جماعة إسرائيل، وإلى وقت خروجه.","16:18":"ثم يأتي إلى المذبح القائم في حضرة الرب ويكفر عنه، فيأخذ من دم الثور ومن دم التيس، ويضع منهما على قرون جوانب المذبح.","16:19":"ويرش عليه من الدم بإصبعه سبع مرات ويطهره ويقدسه من نجاسات بني إسرائيل.","16:20":"وعندما ينتهي من التكفير عن قدس الأقداس، وعن خيمة الاجتماع، وعن المذبح، يأتي بالتيس الحي،","16:21":"ويضع هرون يديه على رأسه، ويعترف بجميع خطايا بني إسرائيل وسيئاتهم وذنوبهم، ويحملها على رأس التيس، ثم يطلقه إلى الصحراء مع شخص تم اختياره لذلك.","16:22":"فيحمل التيس ذنوب الشعب كلها إلى أرض مقفرة، وهناك يطلقه في الصحراء.","16:23":"ثم يدخل هرون إلى خيمة الاجتماع، حيث يخلع الملابس الكتانية التي ارتداها عند دخوله إلى قدس الأقداس ويضعها هناك،","16:24":"ويستحم بماء في مكان مقدس، ثم يرتدي ثيابه ويخرج ليصعد محرقته ومحرقة الشعب، ويكفر عن نفسه وعن الشعب،","16:25":"ويحرق شحم ذبيحة الخطيئة على المذبح،","16:26":"ويغسل ثيابه ويستحم بماء، وبعد ذلك يدخل إلى المخيم.","16:27":"ثم يخرج هرون ثور الخطيئة وتيس الخطيئة اللذين كفر بدمهما في قدس الأقداس إلى خارج المخيم، وتحرقونهما بالنار: جلديهما ولحمهما وروثهما،","16:28":"وعلى من يحرقهما أن يغسل ثيابه ويستحم بماء، وبعد ذلك يدخل إلى المخيم.","16:29":"وإليكم هذه الشريعة الدائمة: إنكم في اليوم العاشر من الشهر السابع (أي شهر أيلول - سبتمبر) تتذللون ولا تقومون بأي عمل. المواطن والغريب النازل في وسطكم على حد سواء،","16:30":"لأنه في هذا اليوم يجري التكفير عنكم، فتطهرون من جميع خطاياكم أمام الرب.","16:31":"إنه يوم راحة مقدسة لكم تتذللون فيه، فريضة دائمة.","16:32":"ويقوم الكاهن الممسوح والمكرس الذي يخلف والده على رئاسة الكهنة بفرائض التكفير وهو لابس ثياب الكتان المقدسة،","16:33":"فيكفر عن قدس الأقداس، وعن خيمة الاجتماع، والمذبح، ويكفر أيضا عن الكهنة وعن كل شعب إسرائيل.","16:34":"وتكون هذه لكم فريضة دائمة للتكفير عن جميع خطايا بني إسرائيل، مرة في السنة». فنفذ هرون ما أمر به موسى.","17:1":"وقال الرب لموسى:","17:2":"«قل لهرون وأبنائه وسائر بني إسرائيل: إليكم ما أوصى به الرب:","17:3":"أي إسرائيلي يذبح قربانا بقرا أو غنما أو معزى في المخيم أو خارج المخيم،","17:4":"وليس عند مدخل خيمة الاجتماع حيث يتوجب عليه تقديمه أمام مسكن الرب، يعتبر قاتلا قد سفك دما، ويجب أن يستأصل ذلك الإنسان من بين شعبه،","17:5":"وذلك لكي يأتي بنو إسرائيل بذبائحهم التي يذبحونها في خلاء الصحراء ويقدموها للرب عند مدخل خيمة الاجتماع، على يد الكاهن، ويقربوها ذبائح سلام للرب.","17:6":"فيرش الكاهن دم الذبيحة على مذبح الرب، عند مدخل خيمة الاجتماع، ويحرق الشحم ليحظى برضى الرب وسروره.","17:7":"ولا يذبحوا ذبائحهم في الخلاء كمحرقات لأوثان التيوس التي يغوون وراءها فتكون لهم هذه فريضة دائمة جيلا بعد جيل.","17:8":"وتقول لهم: أي إسرائيلي، أو غريب من الغرباء المقيمين في وسطكم، يصعد محرقة أو ذبيحة،","17:9":"ولا يأتي بها إلى مدخل خيمة الاجتماع، ولا يقدمها للرب يستأصل من بين شعبه.","17:10":"وأي إسرائيلي أو غريب من المقيمين في وسطكم، يأكل دما، أنقلب عليه وأستأصله من بينكم.","17:11":"لأن حياة الجسد هي في الدم. لهذا وهبتكم إياه لتكفروا عن نفوسكم، لأن الدم يكفر عن النفس.","17:12":"لذلك أوصيت بني إسرائيل ألا يأكلوا دما، وكذلك لا يأكله الغريب المقيم في وسطكم.","17:13":"أي إسرائيلي، أو غريب مقيم في وسطكم، يقتنص حيوانا أو طيرا محللا أكله، يسفك دمه ويغطيه بالتراب،","17:14":"لأن حياة كل مخلوق هي دمه، ولهذا أوصيت بني إسرائيل ألا يأكلوا دم جسد ما، لأن حياة كل جسد هي دمه، وكل من يأكل منه يستأصل.","17:15":"أي إنسان، سواء كان مواطنا أم غريبا، يأكل من جيفة أو فريسة، عليه أن يغسل ثيابه ويستحم بماء، ويبقى نجسا إلى المساء، ثم يصبح طاهرا.","17:16":"ولكن إن لم يغسل ثيابه ولم يستحم يتحمل عقاب ذنبه».","18:1":"وقال الرب لموسى:","18:2":"«أوص بني إسرائيل: أنا الرب إلهكم","18:3":"لا ترتكبوا أعمال أهل مصر التي أقمتم فيها، ولا تعملوا صنيع أهل أرض كنعان التي أنا مدخلكم إليها، ولا تمارسوا فرائضهم،","18:4":"إنما تطبقون أحكامي وتحفظون فرائضي لتسلكوا فيها. أنا الرب إلهكم.","18:5":"احفظوا فرائضي وأحكامي التي إذا أطاعها الإنسان يحيا بها. أنا الرب.","18:6":"لا يقارب إنسان جسد من هو من لحمه ودمه ليعاشره. أنا الرب.","18:7":"لا تتزوج فتاة أباها، ولا ابن أمه إنها أمك فلا تكشف عورتها","18:8":"لا تتزوج امرأة أبيك لأنها زوجة أبيك.","18:9":"لا تتزوج أختك بنت أبيك، أو بنت أمك، سواء ولدت في البيت أم بعيدا عنه، ولا تكشف عورتها.","18:10":"لا تتزوج ابنة ابنك أو ابنة ابنتك، ولا تكشف عورتها لأنها عورتك.","18:11":"لا تتزوج بنت امرأة أبيك المولودة من أبيك، ولا تكشف عورتها لأنها أختك.","18:12":"لا تتزوج أخت أبيك. إنها عمتك.","18:13":"لا تتزوج أخت أمك. إنها خالتك.","18:14":"لا تتزوج فتاة عمها، ولا تعاشر زوجة عمك. إنها عمتك.","18:15":"لا تتزوج كنتك، فإنها امرأة ابنك، ولا تكشف عورتها.","18:16":"لا تتزوج امرأة أخيك، فإنها عورة أخيك.","18:17":"لا تتزوج امرأة وابنتها، ولا تتزوج معها ابنة ابنها أو ابنة بنتها، لأنهما قريبتاها، وإن فعلت ترتكب رذيلة.","18:18":"لا تتزوج امرأة على أختها لتكون ضرة معها في أثناء حياة زوجتك.","18:19":"لا تعاشر امرأة وهي في نجاسة حيضها،","18:20":"ولا تقارب امرأة صاحبك فتعاشرها وتتنجس بها.","18:21":"لا تجز أحد أبنائك في النار قربانا للوثن مولك، لئلا تدنس اسم إلهك. أنا الرب","18:22":"لا تضاجع ذكرا مضاجعة امرأة. إنها رجاسة،","18:23":"ولا تعاشر بهيمة فتتنجس بها، ولا تقف امرأة أمام بهيمة ذكر لتضاجعها. إنه فاحشة.","18:24":"لا تتنجسوا بكل هذه الأعمال المشينة لأن بها تنجست الشعوب التي سأطردها من أمامكم،","18:25":"فقد تنجست بها الأرض، لهذا سأعاقب الأرض بذنبها فتتقيأ سكانها.","18:26":"أما أنتم فاحفظوا فرائضي وأحكامي، ولا تقترفوا شيئا من هذه الرجاسات، المواطن والغريب المقيم في وسطكم على حد سواء.","18:27":"لأن جميع هذه الرجاسات قد ارتكبها أهل البلاد الذين قبلكم، فتنجست الأرض.","18:28":"فلا تنجسوا الأرض بارتكابكم إياها، لئلا تتقيأكم كما تقيأت الأمم التي قبلكم.","18:29":"بل كل من اقترف شيئا من هذه الرجاسات جميعها تستأصل تلك النفس الجانية من بين شعبها.","18:30":"فاحفظوا شعائري لكي لا ترتكبوا شيئا من الممارسات الرجسة التي اقترفت قبلكم، ولا تتنجسوا بها. أنا الرب إلهكم».","19:1":"وقال الرب لموسى:","19:2":"«قل لبني إسرائيل: كونوا قديسين لأني أنا الرب إلهكم قدوس.","19:3":"ليوقر كل إنسان أمه وأباه، وراعوا سبوتي. فأنا الرب إلهكم.","19:4":"ولا تتحولوا لعبادة الأوثان، ولا تصوغوا لأنفسكم آلهة مسبوكة، فأنا الرب إلهكم.","19:5":"ومتى ذبحتم ذبيحة سلام للرب فلتكن ذبيحة رضى.","19:6":"تأكلونها في اليوم الأول والثاني من تقريبها، وفي اليوم الثالث تحرقون ما تبقى منها بالنار.","19:7":"أما الأكل منها في اليوم الثالث فذلك نجاسة منكرة.","19:8":"والآكل منها يعاقب بذنبه لأنه قد دنس قدس الرب فتستأصل تلك النفس من بين شعبها.","19:9":"وعندما تحصد محصول حقلك لا تحصد زواياه ولا تلتقط ما يتناثر من حصيدك.","19:10":"لا ترجع لتجمع بقايا عناقيد كرمك، ولا تلتقط ما ينفرط منها، بل اتركه للمسكين ولعابري السبيل، فأنا الرب إلهكم.","19:11":"لا تسرق، ولا تكذب، ولا تغدر بصاحبك،","19:12":"لا تحلف باسمي كاذبا، فتدنس اسم إلهك. فأنا الرب.","19:13":"لا تظلم قريبك، ولا تسلب ولا ترجئ دفع أجرة أجيرك إلى الغد.","19:14":"لا تشتم الأصم، ولا تضع عثرة في طريق الأعمى، بل اتق إلهك. فأنا الرب.","19:15":"لا تظلموا في القضاء، ولا تتحيزوا لمسكين ولا تحابوا عظيما. احكم لقريبك بالعدل.","19:16":"لا تسع في الوشاية بين شعبك، ولا ترتكب ما يعرض حياة جارك للخطر، فأنا الرب.","19:17":"لا تبغض أخاك في قلبك، بل إنذارا تنذره لئلا تكون شريكا في ذنبه.","19:18":"لا تنتقم ولا تحقد على أحد أبناء شعبك، ولكن تحب قريبك كما تحب نفسك، فأنا الرب.","19:19":"أطيعوا شرائعي. لا تزاوج بهائمك من جنسين، ولا تزرع حقلك من صنفين، ولا تلبس ثوبا منسوجا من مادتين مختلفتين.","19:20":"إن عاشر رجل أمة مخطوبة لرجل آخر، ولم تكن قد افتديت أو أعتقت فليؤدبا، ولا يقتلا، لأنها لم تكن معتوقة.","19:21":"وليأت الرجل بكبش إلى الرب ذبيحة إثم عند مدخل خيمة الاجتماع،","19:22":"فيكفر عنه الكاهن بكبش الإثم أمام الرب من أجل خطيئته التي ارتكبها، فيغفر له الرب خطيئته.","19:23":"ومتى دخلتم ديار كنعان، وغرستم أشجارا ذات أثمار تؤكل فاحسبوا محصول سنواتها الثلاث الأولى محرما، وتكون محظورة عليكم فلا تأكلوا منها،","19:24":"أما ثمر السنة الرابعة فيكون كله مخصصا لتمجيد الرب،","19:25":"وفي السنة الخامسة تأكلون من ثمرها، لتزداد لكم غلتها، فأنا الرب إلهكم.","19:26":"لا تأكلوا لحما بدمه، ولا تمارسوا العرافة والعيافة.","19:27":"لا تحلقوا رؤوسكم حلقا مستديرا، ولا تقلم جانبي لحيتك.","19:28":"لا تجرحوا أجسامكم حزنا على ميت، ولا ترسم وشما عليه. فأنا الرب.","19:29":"لا تدنس ابنتك فتبذلها للفجور، لئلا تزني الأرض وتمتلئ بالرذيلة.","19:30":"راعوا شرائع سبوتي، وأجلوا مقدسي، فأنا الرب.","19:31":"لا تضلوا وراء مستحضري الأرواح، ولا تطلبوا التوابع، فتتنجسوا بهم. فأنا الرب.","19:32":"قف في حضرة كبار السن، ووقر الشيوخ، واتق إلهك، فأنا الرب.","19:33":"إذا أقام في أرضكم غريب فلا تظلموه،","19:34":"وليكن لكم الغريب المقيم عندكم كالمواطن. تحبه كما تحب نفسك، لأنكم كنتم غرباء في أرض مصر. فأنا الرب.","19:35":"لا تجوروا في القضاء، ولا تغشوا في القياس أو الوزن أو الكيل،","19:36":"بل استخدموا موازين عادلة وعيارات عادلة ومكاييل عادلة، فأنا الرب إلهكم الذي أخرجكم من ديار مصر.","19:37":"فاحفظوا جميع فرائضي وأحكامي واعملوا بها، فأنا الرب».","20:1":"وكلم الرب موسى قائلا:","20:2":"«قل لبني إسرائيل: أي إنسان منهم أو من الغرباء المقيمين بينهم قرب للصنم مولك أحد أبنائه، فإنه يقتل إذ يرجمه شعب الأرض بالحجارة.","20:3":"وأنا أنقلب على ذلك الإنسان وأستأصله من بين شعبه، لأنه قرب أحد أبنائه للوثن مولك لينجس قدسي ويدنس اسمي المقدس.","20:4":"وإن تغاضى شعب الأرض عن ذلك الإنسان، عندما قرب لمولك أحد أبنائه، فلم يقتلوه،","20:5":"فإني أنقلب على ذلك الإنسان وعلى عشيرته، وأستأصله مع جميع الضالين وراءه، الزانين مع الصنم مولك من بين شعبهم.","20:6":"وكل نفس غوت وراء أصحاب الجان وتعلقت بالتوابع خيانة لي، أنقلب على تلك النفس وأستأصلها من بين شعبها.","20:7":"فتقدسوا وكونوا قديسين، لأني أنا الرب إلهكم.","20:8":"أطيعوا فرائضي واعملوا بها، فأنا الرب الذي يقدسكم.","20:9":"كل من شتم أباه أو أمه يقتل لأنه شتم أباه أو أمه، لذلك دمه عليه.","20:10":"إذا زنى رجل مع امرأة قريبه، فالزاني والزانية يقتلان.","20:11":"وإذا عاشر رجل زوجة أبيه، فكلاهما يقتلان لأنه كشف عورة أبيه، ويكون دمهما على رأسيهما.","20:12":"وإذا عاشر رجل كنته فكلاهما يقتلان، لأنهما قد اقترفا فاحشة، ويكون دمهما على رأسيهما.","20:13":"وإذا ضاجع رجل ذكرا مضاجعة امرأة، فكلاهما يقتلان لأنهما ارتكبا رجسا. ويكون دمهما على رأسيهما.","20:14":"وإذا تزوج رجل من امرأة وأمها، فتلك رذيلة. ليحرقوا بالنار لئلا تفشو رذيلة بينكم.","20:15":"وإذا عاشر رجل بهيمة فإنه يقتل، وكذلك البهيمة تميتونها أيضا","20:16":"وإذا قاربت امرأة بهيمة ذكرا لتنزوها فأمتهما. كلاهما يقتلان، ويكون دمهما على رأسيهما.","20:17":"إذا تزوج رجل أخته، ابنة أبيه أو ابنة أمه، فذلك عار، ويجب أن يستأصلا على مشهد من أبناء شعبه، لأنه قد كشف عورة أخته، ويعاقب بذنبه.","20:18":"إذا عاشر رجل امرأة حائضا وكشف عورتها فقد عرى ينبوعها، وهي أيضا كشفت عنه. فيجب أن يستأصلا كلاهما من بين شعبهما.","20:19":"إذا عاشر رجل عمته أو خالته، يعاقب كلاهما بذنبهما.","20:20":"وإذا عاشر رجل زوجة عمه فقد كشف عورتها، ويعاقب كلاهما بذنبهما، ويموتان من غير أن يعقبا نسلا.","20:21":"وإذا تزوج رجل امرأة أخيه فذلك نجاسة لأنه كشف عورة أخيه. كلاهما يموتان من غير أن يعقبا نسلا.","20:22":"أطيعوا جميع فرائضي وأحكامي واعملوا بها فلا تنبذكم الأرض التي أنا ذاهب بكم إليها لتقيموا فيها.","20:23":"لا تمارسوا عادات الأمم التي سأطردها من أمامكم، لأنها ارتكبت كل هذه القبائح، فكرهتها،","20:24":"ووعدتكم أن ترثوا ديارها. وأنا أهبكم إياها لتمتلكوها، أرضا تفيض لبنا وعسلا. فأنا الرب إلهكم، ميزتكم عن بقية الشعوب.","20:25":"ميزوا البهائم الطاهرة من النجسة، والطيور النجسة من الطاهرة، فلا تدنسوا أنفسكم بالبهائم والطيور والزواحف التي حظرتها عليكم.","20:26":"وكونوا قديسين لأني أنا قدوس، وقد أفرزتكم من بين الشعوب لتكونوا خاصتي.","20:27":"أي رجل أو امرأة يمارس الوساطة مع الجان أو مناجاة الأرواح، ارجموه ويكون دمه على رأسه».","21:1":"وقال الرب لموسى: «أوص الكهنة أبناء هرون ألا ينجس أحد منهم نفسه بلمس جثة ميت من قومه،","21:2":"إلا إذا كان الميت أقرب أقربائه إليه: أمه وأباه وابنه وابنته وأخاه،","21:3":"وأخته العذراء التي لم تتزوج، المقيمة على مقربة منه، فمن أجلها يتنجس،","21:4":"لأن الكاهن هو رئيس في قومه، وعليه ألا ينجس نفسه شعائريا كغيره من الناس العاديين.","21:5":"ولا يحلق الكاهن شعره قرعة، أو جانبي لحيته، أو يجرح جسده حزنا على ميت.","21:6":"وعلى الكهنة أن يكونوا مفروزين لإلههم. لا يدنسوا اسمه لأنهم يقربون وقائد الرب كأنها طعام يقدمونه لإلههم فيكون مقدسا.","21:7":"ولا يتزوجوا امرأة زانية أو من غير سبطهم، أو امرأة مطلقة من زوجها، لأنهم مقدسون لإلههم،","21:8":"لأن الكاهن مفرز ليقدم ذبائح لإلهك فهو مقدس عندك، لأني أنا الرب مقدسكم، قدوس.","21:9":"وإذا زنت ابنة الكاهن فيجب حرقها لأنها دنست قداسة أبيها.","21:10":"والكاهن الأعظم بين إخوته، الذي سكب على رأسه دهن المسحة، وتكرس ليرتدي الثياب المقدسة، لا يكشف عن رأسه ولا يشق ثيابه حدادا على ميت.","21:11":"وليتفاد الدخول إلى مكان فيه جثة ميت. ولا ينجس نفسه بلمس جثمان ميت، حتى لو كان ذلك جثمان أبيه أو أمه.","21:12":"لا يفارق المقدس في أثناء خدمته، لئلا يدنس مقدس إلهه، لأنه قد تم تكريسه بسكب دهن مسحة إلهه عليه، فأنا الرب.","21:13":"ليتزوج من عذراء،","21:14":"لا من أرملة، ولا مطلقة، ولا زانية مدنسة، بل يتزوج عذراء من سبطه.","21:15":"فلا يدنس نسله بين شعبه، لأني أنا الرب الذي أقدسه».","21:16":"وقال الرب لموسى:","21:17":"«قل لهرون: لا يقرب رجل من نسلك فيه عاهة ذبائح لإلهه على مدى أجيالهم،","21:18":"فكل رجل مصاب بعاهة لا يتقدم سواء أكان أعمى أم أعرج أم مشوه الوجه أم فيه عضو زائد،","21:19":"ولا مكسور اليد أو الرجل،","21:20":"ولا أحدب ولا قزم، أو من في عينه بياض، ولا الأجرب ولا الأكلف ولا مرضوض الخصية.","21:21":"يحظر على كل رجل فيه عاهة من نسل هرون الكاهن أن يتقدم ليقرب ذبائح الرب،","21:22":"ولكنه يأكل من ذبائح إلهه، المقدمة في قدس الأقداس والقدس.","21:23":"غير أنه لا يدخل إلى ما وراء الحجاب، ولا يقترب من المذبح، لأن فيه عيبا، لئلا يدنس مقدسي، لأنني أنا الرب الذي أقدسهم».","21:24":"وهكذا أبلغ موسى هذه الوصايا لهرون وأبنائه وسائر بني إسرائيل.","22:1":"وقال الرب لموسى:","22:2":"«قل لهرون وأبنائه ألا ينتهكوا تقدمات بني إسرائيل التي يقدسونها، ولا يدنسوا اسمي القدوس. فأنا الرب.","22:3":"قل لهم: إياكم على مدى أجيالكم أن يقترب كاهن إلى التقدمات التي يقدسها بنو إسرائيل وهو غير طاهر، فإن تلك النفس تستأصل من أمامي، فأنا الرب.","22:4":"أي كاهن من نسل هرون مصاب بالبرص أو السيلان، لا يأكل من الذبائح المقدسة حتى يطهر، وكذلك كل من لمس شيئا تنجس بجثة ميت، أو شخصا حدث منه قذف منوي.","22:5":"أي كاهن لمس حيوانا أو إنسانا غير طاهر لنجاسة فيه،","22:6":"فاللامس يكون نجسا إلى المساء، ولا يأكل من الذبائح المقدسة، بل يستحم بماء.","22:7":"ولكن متى غربت الشمس يصبح طاهرا، ثم يأكل من الذبائح المقدسة، لأنها طعامه.","22:8":"لا يأكل من جيفة حيوان أو فريسة فيتنجس بها. فأنا الرب.","22:9":"أطيعوا شعائري لئلا تحملوا خطيئتها وتموتوا بسببها لأنكم دنستموها، فأنا الرب الذي أقدسكم.","22:10":"يحظر على غير أسرة الكاهن أن يأكلوا من الذبائح المقدسة، سواء أكان ضيف الكاهن أم أجيره.","22:11":"لكن إذا اشترى الكاهن عبدا بفضة، أو ولد في بيته عبد، فإن ذلك العبد يأكل من طعام الكاهن.","22:12":"وإذا تزوجت ابنة الكاهن من غير كاهن، فإنها لا تأكل من التقدمات المقدسة.","22:13":"أما إذا أصبحت أرملة، أو مطلقة من غير عائل من نسلها، ورجعت إلى بيت أبيها كما في أيام صباها، فإنها تأكل من طعام أبيها. إنما الغريب لا يأكل منه.","22:14":"وإذا أكل أحد من الذبائح المقدسة سهوا، ولم يكن من نسل هرون، يرد للكاهن قيمة ما أكله من الذبيحة، مضافا إليه خمسه.","22:15":"على الكهنة ألا يدنسوا الذبائح التي يحضرها بنو إسرائيل للرب،","22:16":"لأنهم بذلك يحملون الآكلين من الذبائح المقدسة ذنوبا تستوجب العقاب، لأني أنا الرب الذي أقدسها».","22:17":"وقال الرب لموسى:","22:18":"«قل لهرون وأبنائه وسائر إسرائيل: كل إسرائيلي، أو من الغرباء المقيمين في إسرائيل يقدم قربانا، سواء كان وفاء لنذر، أم تقدمة طوعية يقربونها محرقة للرب،","22:19":"تكون محرقة للرضى عنكم، ثورا أو كبشا أو تيسا سليما.","22:20":"لا تقربوا تقدمة فيها عيب، لأنها لن تكون مقبولة للرضى عنكم.","22:21":"وإذا أصعد أحدكم ذبيحة سلام للرب، وفاء لنذر، أو ذبيحة طوعية، فلتكن من البقر أو الغنم، سليمة خالية من كل عيب ليرضى الرب عنكم.","22:22":"لا تقربوا للرب من الذبائح ما هو أعمى أو مكسور أو مجروح أو به بثور أو أجرب أو أكلف، ولا تجعلوا منها وقودا على المذبح للرب.","22:23":"أما الثور أو الحمل الذي فيه عضو زائد أو ناقص، فلك أن تقربه تقدمة طوعية، ولكن ليس وفاء لنذر، فإنه يكون مرفوضا.","22:24":"لا تصعدوا للرب حيوانا ذا خصى مرضوضة أو مسحوقة أو مقطوعة. لا تفعلوا هذا في أرضكم.","22:25":"لا تشتروا مثل هذه الحيوانات من غريب لتقدموها ذبائح لإلهكم، لأنه لن يقبلها منكم، لما فيها من تشويه وعيب».","22:26":"وقال الرب لموسى:","22:27":"«متى ولدت بقرة أو شاة أو عنزة يمكث وليدها معها سبعة أيام، ثم في اليوم الثامن يصح تقديمها قربان وقود للرب.","22:28":"لا تذبحوا البقرة أو الشاة مع ابنها في يوم واحد.","22:29":"ومتى ذبحتم قربان شكر للرب، فاذبحوه للرضى عنكم،","22:30":"وكلوه في اليوم عينه، ولا تبقوا منه شيئا إلى الغد، فأنا الرب.","22:31":"أطيعوا وصاياي واعملوا بها، فأنا الرب.","22:32":"ولا تدنسوا اسمي القدوس، فأتقدس وسط بني إسرائيل، فأنا الرب الذي أقدسكم،","22:33":"والذي أخرجكم من ديار مصر ليكون لكم إلها. أنا الرب».","23:1":"وقال الرب لموسى:","23:2":"«أوص بني إسرائيل: هذه هي مواسمي وأعيادي التي تعلنونها محافل مقدسة.","23:3":"ستة أيام تعملون، أما اليوم السابع فهو سبت راحة ومحفل مقدس. لا تقوموا فيه بأي عمل، بل يكون سبت راحة للرب حيث تقيمون.","23:4":"إليكم مواسم الرب والمحافل المقدسة التي تعيدونها في أوقاتها:","23:5":"في اليوم الرابع عشر من الشهر الأول العبري (أي شهر نيسان - أبريل) بين العشاءين يكون فصح للرب.","23:6":"وفي اليوم الخامس عشر من هذا الشهر يكون عيد الفطير للرب، فتأكلون فطيرا سبعة أيام.","23:7":"في اليوم الأول يكون لكم محفل مقدس، تتوقف فيه جميع الأعمال.","23:8":"ثم تقربون محرقات للرب طوال سبعة أيام. وفي اليوم السابع تقيمون محفلا مقدسا تتعطل فيه جميع الأعمال».","23:9":"وخاطب الرب موسى: «أوص بني إسرائيل وقل لهم:","23:10":"متى دخلتم الأرض التي أهبها لكم وحصدتم غلاتها، تحضرون أول حزمة من حصادكم للكاهن،","23:11":"فيرجح الكاهن الحزمة في اليوم التالي ليوم السبت أمام الرب ليرضى عنكم.","23:12":"وتقدمون يوم ترجيح الحزمة خروفا سليما محرقة للرب،","23:13":"مع عشرين (نحو خمسة لترات) من دقيق معجون بالزيت وقودا للرب لتحظوا برضاه. وكذلك تقدمون سكيبه ربع الهين (نحو لتر) من الخمر.","23:14":"لا تأكلوا من الغلة الجديدة، لا دقيقا مخبوزا ولا فريكا ولا سويقا إلى اليوم الذي تحضرون فيه قربان إلهكم، فتكون هذه عليكم فريضة دائمة جيلا بعد جيل.","23:15":"ثم تحسبون سبعة أسابيع كاملة، ابتداء من اليوم التالي للسبت الذي تحضرون فيه حزمة الترجيح،","23:16":"فتحسبون خمسين يوما إلى اليوم التالي للسبت السابع، ثم تقربون تقدمة جديدة للرب.","23:17":"فتأتون من مساكنكم بخبز ترجيح، رغيفين مقدارهما عشرين (نحو خمسة لترات) من دقيق مخبوزين بخمير، فيكونان باكورة للرب.","23:18":"وتقدمون مع الخبز سبعة خراف سليمة حولية وثورا واحدا وكبشين وسكيب خمر. فتكون جميعها محرقة ووقود رضى وسرور للرب.","23:19":"وتقربون تيسا واحدا من المعز ذبيحة خطيئة وخروفين حوليين ذبيحة سلام.","23:20":"فيرجحها الكاهن أمام الرب مع خبز الباكورة والخروفين، فتكون مقدسة للرب نصيبا للكاهن.","23:21":"وتخصصون ذلك اليوم عينه ليكون محفلا مقدسا لكم، تتعطل فيه جميع الأعمال، فتكون عليكم فريضة دائمة حيث تقيمون جيلا بعد جيل.","23:22":"وعندما تستوفون حصاد غلاتكم، اتركوا زوايا حقولكم غير محصودة، ولا تلتقطوا ما يقع منها على الأرض، بل اتركوه للمسكين وعابر السبيل. فأنا الرب إلهكم».","23:23":"وقال الرب لموسى:","23:24":"«أوص بني إسرائيل وقل لهم: يكون لكم اليوم الأول من الشهر السابع (أي شهر أيلول - سبتمبر) يوم عطلة فيه تحتفلون احتفالا مقدسا، تنفخون فيه بالأبواق.","23:25":"تتوقفون فيه عن أعمالكم وتصعدون تقدمات محرقات للرب».","23:26":"وقال الرب لموسى:","23:27":"«ويكون اليوم العاشر من هذا الشهر السابع يوم كفارة، تحتفلون فيه احتفالا مقدسا، وتذللون نفوسكم، وتقربون محرقات للرب،","23:28":"وتتوقفون فيه أيضا عن أعمالكم، لأنه يوم كفارة للتكفير عنكم أمام الرب إلهكم.","23:29":"وكل نفس لا تتذلل في هذا اليوم تستأصل من بين شعبها","23:30":"وأبيد كل من لا يتوقف عن عمله في هذا اليوم.","23:31":"إياكم والقيام بعمل ما. إنها فريضة دائمة عليكم جيلا بعد جيل حيث تقيمون.","23:32":"إنه سبت راحة لكم تتذللون فيه، فتستريحون من مساء اليوم التاسع حتى مساء اليوم التالي».","23:33":"وقال الرب لموسى:","23:34":"«أوص بني إسرائيل أن يحتفلوا بعيد الخيام في اليوم الخامس عشر من الشهر السابع. يحتفلون للرب سبعة أيام.","23:35":"تجتمعون في اليوم الأول في محفل مقدس، تتوقف فيه جميع الأعمال،","23:36":"ثم تثابرون على تقريب محرقات للرب طوال سبعة أيام. وفي اليوم الثامن تجتمعون لاحتفال مقدس تقدمون فيه محرقات للرب، وتعتكفون للعبادة. وفي هذا اليوم تتوقف أيضا جميع الأعمال.","23:37":"هذه هي أعياد الرب التي تحتفلون فيها احتفالا مقدسا لتقريب محرقات للرب، محرقة وتقدمة وذبيحة وخمرا للرب، كل يوم بيومه،","23:38":"فتكون هذه المحرقات علاوة على تقدمات سبوت الرب، وعلاوة على عطاياكم وجميع نذوركم وتبرعاتكم التي تقدمونها للرب.","23:39":"وتعيدون في اليوم الخامس عشر من الشهر السابع عيدا للرب، لأن فيه تجمعون غلة أرضكم. تعيدون للرب سبعة أيام، فيكون اليوم الثامن عطلة.","23:40":"في اليوم الأول تجمعون ثمار أشجار نضرة وسعف نخل وأغصان أشجار كثيفة الورق، وأغصان صفصاف نهري، وتفرحون أمام الرب إلهكم سبعة أيام.","23:41":"سبعة أيام في السنة من الشهر السابع تحتفلون به عيدا للرب. ويكون هذا فريضة دائمة عليكم جيلا بعد جيل،","23:42":"فيقيم كل أبناء أرض إسرائيل في خيام سبعة أيام.","23:43":"لكي تتذكر أجيالكم أنني أسكنت أبناء إسرائيل في خيام عندما أخرجتهم من أرض مصر. فأنا الرب إلهكم».","23:44":"وهكذا أبلغ موسى بني إسرائيل بأعياد الرب.","24:1":"وقال الرب لموسى:","24:2":"«أوص بني إسرائيل أن يحضروا لك زيت زيتون مرضوض نقيا لإنارة السرج الدائمة،","24:3":"القائمة خارج حجاب الشهادة في خيمة الاجتماع، فيقوم هرون بالإشراف على إنارتها أمام الرب من المساء إلى الصباح، فتكون فريضة أبدية جيلا بعد جيل","24:4":"إذ يتوجب دائما إنارة السرج التي على المنارة الذهبية النقية أمام الرب.","24:5":"وعليك أن تأخذ دقيقا وتخبزه، صانعا منه اثني عشر رغيفا، على أن يكون مقدار كل رغيف عشرين (نحو خمسة لترات).","24:6":"وترتبها صفين، كل صف من ستة أرغفة، على المائدة الطاهرة أمام الرب.","24:7":"وتضع على كل صف لبانا، فيكون للخبز تذكارا، وليكون وقودا للرب.","24:8":"وترتب هذا الخبز، بانتظام، كل يوم سبت أمام الرب، من أجل بني إسرائيل ميثاقا أبديا.","24:9":"ويكون هذا الخبز من نصيب هرون وأبنائه، فيأكلونه في مكان مقدس، لأنه قدس أقداس له من محرقات الرب، فريضة دائمة».","24:10":"وحدث أن خرج ابن امرأة إسرائيلية، أبوه رجل مصري، وسط بني إسرائيل وتخاصم في المخيم مع رجل إسرائيلي.","24:11":"فجدف ابن الإسرائيلية، المدعوة شلومية بنت دبري، من سبط دان على اسم الرب وسبه، فأحضروه إلى موسى،","24:12":"وزجوه في السجن ريثما يصدر الرب حكمه عليه.","24:13":"فقال الرب لموسى:","24:14":"«خذ الشاتم إلى خارج المخيم، واجعل جميع الذين سمعوا تجديفه يضعون أيديهم على رأسه، ويرجمه كل الشعب.","24:15":"وقل لبني إسرائيل: كل من شتم إلهه يعاقب بذنبه.","24:16":"ومن جدف على اسم الرب يقتل، إذ يرجمه الشعب رجما، الغريب كالإسرائيلي يعاقب بالقتل عند تجديفه على اسم الرب.","24:17":"وإذا قتل أحد إنسانا فإنه يقتل.","24:18":"ومن أمات بهيمة جاره يعوض عنها نفسا بنفس.","24:19":"ومن أوقع بقريبه ضررا فبمثل ما أوقع يوقع به.","24:20":"كسر بكسر وعين بعين وسن بسن. وكما أنزل بسواه من أذى ينزل به.","24:21":"من قتل بهيمة جاره يعوض عنها، ومن قتل إنسانا يقتل.","24:22":"حكم واحد يطبق عليكم، الغريب كالإسرائيلي، إني أنا الرب إلهكم».","24:23":"فأمر موسى بني إسرائيل أن يخرجوا الشاتم إلى خارج المخيم ويرجموه بالحجارة، فنفذ بنو إسرائيل أمر الرب لموسى.","25:1":"وقال الرب لموسى في جبل سيناء:","25:2":"«أوص بني إسرائيل: متى جئتم إلى الأرض التي أهبكم إياها، لا تزرعوها في السنة السابعة.","25:3":"ازرع حقلك ست سنوات، وقلم كرمك ست سنوات، واجمع غلتهما.","25:4":"وأما السنة السابعة ففيها تريح الأرض وتعطلها سبتا للرب. لا تزرع فيها حقلك ولا تقلم كرمك.","25:5":"لا تحصد زرعك الذي نما بنفسه، ولا تقطف عنب كرمك المحول، بل تكون سنة راحة للأرض.","25:6":"وما تغله الأرض في سنة الراحة يكون طعاما لك ولعبدك وأمتك وأجيرك والمستوطن النازل عندك،","25:7":"وكذلك تكون كل غلتها طعاما للبهائم وللحيوان الراعي فيها.","25:8":"وبعد انقضاء تسع وأربعين سنة، أي بعد سبع سبوت من السنين،","25:9":"في اليوم العاشر من الشهر السابع، من كل خمسين سنة عبرية، تنفخون بوق الهتاف في يوم الكفارة في جميع أرضكم،","25:10":"وتقدسون السنة الخمسين وتعلنون فيها العتق لجميع سكانها، فتكون لكم يوبيلا، وترجعون كل واحد إلى ملكه وعشيرته.","25:11":"وتكون لكم السنة الخمسون هذه يوبيلا، لا تزرعوا فيها ولا تحصدوا غلتها ولا تقطفوا كرمها المحول.","25:12":"إنها يوبيل، سنة مقدسة لكم. لا تأكلوا إلا ما يجنى مباشرة من الحقل.","25:13":"وفي سنة اليوبيل هذه يرتد كل واحد إلى ملكه.","25:14":"فإن بعت مواطنك، أو اشتريت منه، فلا تظلمه.","25:15":"يكون شراؤك من صاحبك وفقا لعدد السنين بعد اليوبيل، وبيعه لك يكون بناء على سني الغلة.","25:16":"فكلما كثرت السنون تزيد قيمته، وكلما قلت السنون ينخفض ثمنه، لأنه يبيعك بناء على عدد الغلات،","25:17":"فلا يظلمن أحد صاحبه، بل اتق إلهك، لأني أنا الرب إلهكم.","25:18":"فاعملوا بفرائضي وراعوا أحكامي ومارسوها، لتسكنوا في الأرض آمنين،","25:19":"عندئذ تغل الأرض ثمرها، فتأكلون وتشبعون وتسكنون عليها آمنين.","25:20":"وإن قلتم: ماذا نأكل في السنة السابعة إن لم نزرع ولم نجمع غلتنا؟","25:21":"ها أنا آمر ببركتي لكم في السنة السادسة فتغل لثلاث سنين،","25:22":"فتزرعون في السنة الثامنة وتأكلون من الغلة القديمة إلى أن يتم حصيد موسم السنة التاسعة.","25:23":"أما الأرض فلا تباع مطلقا لأن لي الأرض، وأنتم غرباء ونزلاء عندي.","25:24":"بل في كل عقد بيع تضعون شرط فكاك للأرض.","25:25":"وإذا افتقر مواطنك وباع بعض ملكه فليأت أقرب أقربائه ويفك مبيع قريبه","25:26":"ومن لم يكن له قريب، واستطاع الحصول على مقدار كاف من المال لفك البيع،","25:27":"فليحسب عدد السنوات التي انقضت على المبيع، وما هو متبق منها حتى حلول سنة اليوبيل، فيدفع للمشتري ما يعادل غلال السنوات المتبقية، ويسترد ملكه","25:28":"وإن لم يتوافر لديه المال لاسترداد مبيعه من يد الشاري، فلينتظر حتى حلول سنة اليوبيل ليسترد ملكه.","25:29":"وإذا باع إنسان بيتا للسكنى في مدينة مسورة يحق استرداده في خلال سنة من بيعه.","25:30":"وإن عجز عن فكاكه قبل انقضاء سنة، يصبح البيت الذي في المدينة المسورة من حق شاريه ونسله لا يرد في سنة اليوبيل.","25:31":"أما البيوت المباعة في القرى غير المسورة فإنها تعامل معاملة الحقول الزراعية، قابلة للفكاك والاسترداد في سنة اليوبيل.","25:32":"أما بيوت اللاويين القائمة في مدن اللاويين المسورة، فإن للاويين حق استردادها دائما،","25:33":"فبيوت اللاويين قابلة للفكاك وتسترد في سنة اليوبيل، لأن بيوتهم في مدن اللاويين هي ملكهم بين بني إسرائيل.","25:34":"أما المزارع المحيطة بمدنهم فلا تباع، لأنها ملك أبدي لهم.","25:35":"وإذا افتقر أخوك وعجز عن إعالة نفسه في وسطك، فأعنه، سواء كان غريبا أو مواطنا، ليتمكن من العيش معك.","25:36":"اتق إلهك ولا تأخذ منه ربا ولا ربحا، ليتمكن من العيش في وسطك","25:37":"لا تقرضه فضتك بربا، ولا تبعه طعامك بربح.","25:38":"أنا الرب إلهكم الذي أخرجكم من ديار مصر ليهبكم أرض كنعان، فيكون لكم إلها.","25:39":"وإذا افتقر أخوك وبيع لك عبدا، فلا تعامله كعبد،","25:40":"بل ليكن عندك كأجير أو نزيل، فيخدمك حتى حلول سنة اليوبيل،","25:41":"ثم تعتقه هو وأولاده، ويعود إلى قومه، ويرجع إلى ملك آبائه،","25:42":"لأن بني إسرائيل عبيدي الذين أخرجتهم من مصر، لا يباعون كالعبيد.","25:43":"لا تطغ بتسلطك، بل اتق إلهك،","25:44":"وليكن عبيدكم وإماؤكم من الشعوب التي حولكم، منها تقتنون عبيدا وإماء،","25:45":"وكذلك من أبناء المستوطنين النازلين عندكم، فمنهم ومن عشائرهم، الذين عندكم المولودين في أرضكم، تقتنون عبيدا لكم.","25:46":"وتورثونهم لبنيكم من بعدكم ميراث ملك، فيكونون عبيدا لكم إلى الأبد. وأما إخوتكم من بني إسرائيل فلا تطغوا بتسلطكم عليهم.","25:47":"وإذا اغتنى غريب أو نزيل مقيم في وسطكم، وافتقر أخوك فبيع للغريب المستوطن عندك، أو لنسل عشيرته،","25:48":"فليفكه واحد من أقربائه بعد بيعه، لأنه يملك حق الانعتاق.","25:49":"أو يفكه عمه أو ابن عمه أو أحد أقربائه من أبناء عشيرته، أو يسترد هو نفسه حريته إذا حصل على ما يكفي من مال،","25:50":"فيتحاسب مع شاريه منذ سنة بيعه حتى سنة اليوبيل، فيكون ثمن عتقه وفقا لما يدفع لأجير، لذلك العدد من السنوات.","25:51":"وإذا كانت السنوات الباقية حتى حلول اليوبيل كثيرة، فعليه أن يدفع نسبة أكبر من أصل الثمن الذي دفع في شرائه، إستردادا لحريته.","25:52":"وإن كانت السنوات الباقية حتى سنة اليوبيل قليلة، فعليه أن يحسب عدد السنوات ويدفع وفقها في سبيل فكاكه.","25:53":"وعلى الأجنبي أن يعامله كأجير من سنة إلى سنة، ولا يقسو عليه أمام عينيك.","25:54":"وإن لم يوجد سبيل لفكاكه، فإنه يعتق هو وبنوه معه في سنة اليوبيل.","25:55":"لأن بني إسرائيل لي عبيد. هم عبيدي الذين أخرجتهم من مصر. أنا الرب إلهكم.","26:1":"لا تصنعوا لكم أصناما، ولا تقيموا لكم تماثيل منحوتة، أو أنصابا مقدسة، ولا ترفعوا حجرا مصورا في أرضكم لتسجدوا له، لأني أنا الرب إلهكم.","26:2":"راعوا راحة أيام السبت، ووقروا مقدسي، فأنا الرب.","26:3":"إن سلكتم في فرائضي وأطعتم وصاياي وعملتم بها،","26:4":"فإني أسكب عليكم المطر في أوانه، وتعطي الأرض غلتها، وتثمر أشجار الحقل،","26:5":"فتستمر دراسة حنطتكم حتى موعد قطاف العنب، ويستمر قطاف العنب حتى موسم الزراعة، فتأكلون خبزكم حتى الشبع، وتسكنون في أرضكم آمنين.","26:6":"وأشيع سلاما في الأرض، فتنامون مطمئنين، وأبيد الوحوش البرية من الأرض ولا يجتاز سيف في دياركم.","26:7":"وتطردون أعداءكم فيسقطون أمامكم بالسيف.","26:8":"خمسة منكم يطردون مئة، ومئة منكم يطردون عشرة آلاف. ويتساقط أعداؤكم أمامكم بحد السيف،","26:9":"وأرعاكم بعنايتي، وأنميكم وأكثركم، وأفي بميثاقي معكم،","26:10":"وتظلون تأكلون من الغلال القديمة حين تفرغونها من مخازنها لتوسعوا لغلات السنة الجديدة.","26:11":"وأقيم مسكني في وسطكم ولا أخذلكم،","26:12":"وأسير بينكم وأكون إلهكم، وأنتم تكونون لي شعبا.","26:13":"أنا الرب إلهكم أخرجتكم من مصر، وحطمت أغلال قيودكم ورفعت شأنكم، لكي لا تظلوا عبيدا للمصريين في ما بعد.","26:14":"ولكن إن عصيتموني ولم تعملوا بكل هذه الوصايا،","26:15":"وإن تنكرتم لفرائضي وكرهتم أحكامي ولم تعملوا بكل وصاياي، بل نكثتم ميثاقي،","26:16":"فإني أبتليكم بالرعب المفاجئ وداء السل والحمى التي تفني العينين وتتلف النفس، وتزرعون على غير طائل، وينهب أعداؤكم زرعكم.","26:17":"وأنقلب عليكم فتنهزمون أمام أعدائكم، ويتحكم بكم مبغضوكم وتهربون من غير طارد لكم.","26:18":"وإن أمعنتم في عصيانكم أزيد من عقابكم سبع مرات وفقا لخطاياكم.","26:19":"أذل غطرستكم، وأجعل سماءكم كالحديد لا تمطر وأرضكم كالنحاس لا تغل","26:20":"فيذهب جهدكم باطلا لأن أرضكم لن تعطي غلتها، وأشجار الأرض لن تعطي أثمارها.","26:21":"وإن واظبتم على عصيانكم وأبيتم طاعتي، أضاعف عقابي لكم سبع مرات وفقا لخطاياكم.","26:22":"وأطلق عليكم وحوش الصحراء فتفترس أولادكم وتهلك بهائمكم، وتنقص من عددكم، فتقفر طرقاتكم.","26:23":"وإن لم تتعظوا، وتماديتم في عصيانكم،","26:24":"أنقلب عليكم وأزيد في بلائكم سبع مرات وفقا لخطاياكم.","26:25":"أسلط عليكم سيف العدو. فينتقم منكم لنقضكم ميثاقي، فتحتمون بمدنكم حيث أرسل عليكم الوباء وتسلمون إلى يد العدو","26:26":"وحين أقطع عنكم مؤونة الدقيق، تخبز عشر نساء خبزكم في فرن واحد لقلة الدقيق، وتقسمون الخبز بالميزان فتأكلون ولا تشبعون.","26:27":"وإن لم يجد هذا العقاب في تأديبكم، فتماديتم في عصيانكم،","26:28":"فإني أزيد في احتدام غضبي، من عدائي لكم وأضاعف عقابي سبع مرات أخرى وفقا لخطاياكم،","26:29":"فتأكلون لحم أبنائكم وبناتكم.","26:30":"وأهدم مذابح مرتفعاتكم، وأحطم أصنام شموسكم وأكوم جثثكم فوق بقايا أصنامكم، وتنبذكم نفسي.","26:31":"وأحول مدنكم إلى خرائب، وأجعل مقادسكم موحشة، ولا أبتهج برائحة تقدمات سروركم،","26:32":"وأجعل الأرض قفرا فيرتاع من وحشتها أعداؤكم الساكنون فيها","26:33":"وأشتتكم بين الشعوب، وأجرد عليكم سيفي، وألاحقكم، وأحول أرضكم إلى قفر ومدنكم إلى خرائب.","26:34":"عندئذ تستوفي الأرض راحة سبوتها طوال سني وحشتها وأنتم مشتتون في ديار أعدائكم. حينئذ ترتاح الأرض وتستوفي سني سبوتها.","26:35":"فتعوض في أيام وحشتها عن راحتها التي لم تنعم بها في سنوات سبوتكم عندما كنتم تقيمون عليها.","26:36":"أما الباقون منكم في أرض أعدائكم، فإني ألقي الرعب في قلوبهم فيهربون من حفيف ورقة تسوقها الريح، وكأنهم يهربون من السيف، ويسقطون وليس ثمة من طارد لهم.","26:37":"ويعثر بعضهم ببعض كمن يفر من أمام سيف من غير طارد لهم، ولا تثبتون أمام أعدائكم","26:38":"فتهلكون بين الشعوب، وتبتلعكم أرض أعدائكم.","26:39":"أما بقيتكم فتفنى بذنوبها وذنوب آبائها في أرض أعدائكم كما فني آباؤهم من قبلهم.","26:40":"ولكن إن اعترفوا بخطاياهم وخطايا آبائهم وبخيانتهم لي وعداوتهم،","26:41":"التي جعلتني أنقلب عليهم وأنفيهم إلى أرض أعدائهم، وإن خضعت قلوبهم النجسة بعد أن استوفوا عقاب خطاياهم،","26:42":"فإني أذكر عهدي مع يعقوب، عهدي مع إسحاق، وعهدي مع إبراهيم، وأذكر الأرض،","26:43":"التي أقفرت منهم، فاستوفت راحة سبوتها في أثناء نفيهم عنها، ويكونون آنئذ قد استوفوا عقاب خطاياهم لأنهم تنكروا لشرائعي وكرهوا فرائضي.","26:44":"ولكن على الرغم من ذلك فإنني لم أنبذهم وهم في أرض أعدائهم، ولا كرهتهم حتى أبيدهم وأنقض عهدي معهم، لأني أنا الرب إلههم،","26:45":"بل أذكر عهدي مع آبائهم الأولين الذين أخرجتهم من ديار مصر على مشهد من الشعوب لأكون لهم إلها. أنا الرب».","26:46":"هذه هي الفرائض والأحكام والشرائع التي أقامها الرب بينه وبين بني إسرائيل في جبل سيناء على لسان موسى.","27:1":"وقال الرب لموسى:","27:2":"«أوص بني إسرائيل أنه إذا نذر أحد نفسه أو سواه للرب فإن فداء المنذور يكون بموجب جدول تقديرك التالي حسب موازين القدس:","27:3":"يفتدى كل ذكر من ابن عشرين إلى ابن ستين سنة بخمسين شاقلا (نحو ست مئة جرام) من الفضة.","27:4":"وتفتدي كل امرأة منذورة بثلاثين شاقلا (نحو ثلاث مئة وستين جراما) من الفضة.","27:5":"أما إن كان المنذور ذكرا من ابن خمس سنوات إلى عشرين فيفتدى بعشرين شاقلا (نحو مئتين وأربعين جراما) من الفضة. أما فداء الأنثى فيكون عشرة شواقل (نحو مئة وعشرين جراما).","27:6":"وإن كان عمر المنذور بين شهر وخمس سنوات فيفتدى الذكر بخمسة شواقل (نحو ستين جراما) من الفضة، والأنثى بثلاثة شواقل (نحو ستة وثلاثين جراما).","27:7":"وإن كان المنذور ذكرا ابن ستين سنة فما فوق يفتدى بخمسة عشر شاقلا (نحو مئة وثمانين جراما)؛ أما الأنثى فتفتدى بعشرة شواقل (نحو مئة وعشرين جراما).","27:8":"وإن كان الناذر فقيرا يعجز عن دفع القيمة المقدرة، يحضر إلى الكاهن فيقدر فداءه وفقا لقدرة الناذر المادية.","27:9":"وإن كان المنذور بهيمة مما يقدمونه قربانا للرب فإن هذه البهيمة تصبح قدسا للرب.","27:10":"لا يغيره الناذر ولا يبدله جيدا برديء أو رديئا بجيد. وإن استبدل بهيمة بأخرى فإنها تكون هي وبديلها قدسا للرب.","27:11":"وإن كان النذر بهيمة نجسة، لا يجوز تقريبها للرب، يحضر الناذر البهيمة أمام الكاهن،","27:12":"فيقدر قيمتها، سواء كانت جيدة أم رديئة، وحسب تقدير الكاهن يدفع الناذر قيمتها.","27:13":"فإن فكها فعليه أن يضيف خمسها على تقدير الكاهن.","27:14":"وإن كرس إنسان بيته قدسا للرب، يقدر الكاهن قيمته وفقا لحالته من الجودة والرداءة. وحسب تقدير الكاهن هكذا يكون.","27:15":"فإذا رغب المكرس أن يفك بيته، يضيف على تقدير الكاهن ما يعادل خمسه ويسترده.","27:16":"وإن كرس إنسان جزءا من حقل يملكه للرب، فإن تقديرك قيمته يكون على قدر ما يزرع فيه من بذار، فيكون لكل بذار حومر (نحو مئتين وأربعين لترا) من بذار الشعير خمسون شاقلا (نحو ست مئة جرام) من الفضة","27:17":"فإن كرس حقله في سنة اليوبيل فإنه يقوم بدفع ما تم تقديره.","27:18":"وإن كرس حقله بعد سنة اليوبيل فعلى الكاهن أن يقدر قيمة الفضة وفقا لعدد السنين الباقية لحلول سنة اليوبيل، فيتم إنقاص تقديرك.","27:19":"فإن فك المكرس الحقل يضيف على تقديرك خمسه من الفضة ويسترده.","27:20":"لكن إن لم يفك الحقل، وباعه لإنسان آخر فإنه لا يسترده أبدا،","27:21":"بل يصبح الحقل في سنة اليوبيل قدسا للرب، ويكون ملكا للكاهن.","27:22":"وإن اشترى حقلا ولم يكن قد آل إليه بالميراث، وكرسه للرب،","27:23":"يقدر الكاهن ثمنه حسب تقديرك إلى سنة اليوبيل. فيدفع في ذلك اليوم مقدار تقديرك، قدسا للرب.","27:24":"وفي سنة اليوبيل يرد الحقل إلى مالكه الذي باعه إياه،","27:25":"أما تقديرك فيكون قائما على شاقل المقدس، فكل عشرين جيرة تعادل شاقلا، (أي اثني عشر جراما) من الفضة.","27:26":"لا يقدس أحد بكرا من البهائم فإنه يفرز للرب، سواء كان ثورا أم شاة فهو للرب.","27:27":"أما إن كان من البهائم النجسة، فعلى صاحبه أن يفديه حسب تقديرك، ويضيف على ذلك خمسه وإن لم يفده يباع وفقا لتقديرك.","27:28":"لكن كل ما يوقفه إنسان للرب مما يملكه من الناس والبهائم والحقول الموروثة فلا يباع ولا يفتدى، لأن كل وقف هو قدس أقداس للرب.","27:29":"كل ما يصدر الأمر بتحريمه من الناس لا يفدى بل يقتل حتما.","27:30":"كل عشور غلات الأرض من الحبوب وأثمار الشجر هو للرب وقدس له.","27:31":"وإن فك إنسان بعض عشره يضيف عليه خمس ثمنه.","27:32":"أما كل عشر البقر والغنم فيكون العاشر منها قدسا للرب وفقا لإحصاء الراعي","27:33":"لا فرق إن كان جيدا أو رديا، ولا يجري تبديله؛ وإن أبدل يكون هو وبديله قدسا لا يفتدى».","27:34":"هذه هي الوصايا التي أمر الرب موسى أن يبلغها لبني إسرائيل في جبل سيناء."};
